(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0021.js"] = [{"id":"poem-89ed59905f35d18e162902cc","title":"春草凝露","author":"张友正","dynasty":"唐","verses":["苍苍芳草色，含露对青春。","已赖阳和长，仍慙润泽频。","日临残未滴，风度欲成津。","蕙叶垂偏重，兰丛洗转新。","将行愁裛迳，欲采畏濡身。","独爱池塘畔，清华远袭人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8bd75875-20ad-4b0c-8e73-948d5f282e4b","tags":[]},{"id":"poem-89f679d39accdf22f86c20ed","title":"送襄阳李尚书","author":"李益","dynasty":"唐","verses":["天寒发梅柳，忆昔到襄州。","树暖然红烛，江清展碧油。","风烟临岘首，云水接昭丘。","俗尚春秋学，词称文选楼。","都门送旌节，符竹领诸侯。","汉沔分戎寄，黎元减圣忧。","时追山简兴，本自习家流。","莫废思康乐，诗情满沃洲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b22cb818-b07a-4024-855d-c3734cd1d237","tags":[]},{"id":"poem-8a00a3655e13302a1fb10d15","title":"十无诗寄桂府杨中丞 九","author":"赵嘏","dynasty":"唐","verses":["僻爱江山俯坐隅，人间不是便为图。","尊前为问神仙伴，肯向三清慰荐无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-acd0c10e-587a-4b45-91a3-34ae63bd9658","tags":[]},{"id":"poem-8a017dad5190863248a9a8a0","title":"送薛逢之宣州谒废使","author":"皎然","dynasty":"唐","verses":["六月鹏尽化，鸿飞独冥冥。","秋烽家不定，险路客频经。","牛渚何时到，渔船几处停。","遥知咏史夜，谢守月中听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6163842c-cd07-4922-884f-b8ca285e40dd","tags":[]},{"id":"poem-8a0c64e0d9a717ee0674099a","title":"雁过声","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)昨宵际晚时，见小叔背负员外归。","穿一领百衲破衣，睚睚瘦得不中觑，铁心肠见了珠泪垂。","(贴)一饭未曾举箸，员外酒醒喝起，便道他偷了环儿。","更不分说几句，便拳踢乱打逐出去，破窑内受苦伊怎知！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1788","tags":[]},{"id":"poem-8a0d2afacb233acd2ae64b08","title":"祀风师乐章 送神","author":"包佶","dynasty":"唐","verses":["微穆敷华能应节，飘扬发彩宜行庆。","送迎灵驾神心飨，跪拜灵坛礼容盛。","气和草木发萌芽，德畅禽鱼遂翔泳。","永望翠盖逐流云，自兹率土调春令。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-43745683-136f-47c7-9e3c-0bdba015e213","tags":[]},{"id":"poem-8a0e0700a96611ab02460ae7","title":"和寿中丞伤猿","author":"李洞","dynasty":"唐","verses":["遗挂朱栏锁半寻，清声难买恨黄金。","悬崖接果今何在，浅井窥星影已沉。","归宅叶铺曾睡石，入朝灯照旧啼林。","小山罢遶随湘客，高树休升对岳禽。","天竺省怜伤倍切，亲知宽和思难任。","相门恩重无由报，竟托仙郎日夜吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-da446e03-8b8b-4974-acbe-a962685e4264","tags":[]},{"id":"poem-8a2c887318b31eb7d0ac3c8e","title":"悲秋","author":"卢殷","dynasty":"唐","verses":["秋空雁度青天远，疎树蝉嘶白露寒。","阶下败兰犹有气，手中团扇渐无端。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b57f5d4c-ed74-4a50-b93b-8bda505ca726","tags":[]},{"id":"poem-8a2d62b3ecb47823685ff638","title":"书怀寄友人","author":"沈颜","dynasty":"唐","verses":["江湖劳遍寻，祗自长愁襟。","到处慵开口，何人可话心。","登楼得句远，望月抒情深。","却忆山斋后，猿声相伴吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ef77519a-bf95-4d2d-82f8-6b45675ede51","tags":[]},{"id":"poem-8a3675a44a9fdab56a9c23c6","title":"使辽作十四首  其五","author":"刘跂","dynasty":"宋","verses":["寒日川原暗，颠风草木昏。","捉襟愁肘见，语客畏声吞。","旷荡疑人少，仓皇觉马奔。","勿惊销髀肉，长遣节旄存。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9ff7fea0-728d-4b16-b16b-b39fde66f6df","tags":[]},{"id":"poem-8a3678b7b9baf04b915fc109","title":"何草不黄","author":"佚名","dynasty":"先秦","verses":["何草不黄？何日不行？何人不将？经营四方。","何草不玄？何人不矜？哀我征夫，独为匪民。","匪兕匪虎，率彼旷野。哀我征夫，朝夕不暇。","有芃者狐，率彼幽草。有栈之车，行彼周道。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-233","tags":[]},{"id":"poem-8a3c58fa51a94cba606c965b","title":"横吹曲辞 出塞","author":"王维","dynasty":"唐","verses":["居延城外猎天骄，白草连天野火烧。","暮云空碛时驱马，秋日平原好射雕。","护羌校尉朝乘障，破虏将军夜渡辽。","玉靶角弓珠勒马，汉家将赐霍嫖姚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e4fdb460-0944-4976-85a9-527bc87f7d7a","tags":["边塞"]},{"id":"poem-8a3e1d498451889a8af5fea0","title":"胡捣练","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["辞别去，到荒丘，只愁出路煞生受。","画取真容聊借手，逢人将此免哀求。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5158","tags":[]},{"id":"poem-8a4d36096108d19c4cf89675","title":"乾元中寓居同谷县作歌七首 七","author":"杜甫","dynasty":"唐","verses":["男儿生不成名身已老，三年饥走荒山道。","长安卿相多少年，富贵应须致身早。","山中儒生旧相识，但话宿昔伤怀抱。","鸣呼七歌兮悄终曲，仰视皇天白日速。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1c556427-1203-45cd-b593-eab55e582569","tags":[]},{"id":"poem-8a550c936f2c63376308a3b1","title":"三君咏 郭代公","author":"高适","dynasty":"唐","verses":["代公实英迈，津涯浩难识。","拥兵抗矫征，仗节归有德。","纵横负才智，顾盻安社稷。","流落勿重陈，怀哉为凄恻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0c521179-7dd9-49a9-8b29-c7331d8870d0","tags":[]},{"id":"poem-8a57b772846578082c9f0be0","title":"瑞香","author":"释居简","dynasty":"宋","verses":["谱上先题五老名，宫袍云锦旧为隣。","华风似惜诗人老，一样裁成紫绮新。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-39bb1740-dd0d-495c-8b22-6f74a3224fe9","tags":[]},{"id":"poem-8a5944957a954cb5f373b43f","title":"光化踏青有感","author":"司空图","dynasty":"唐","verses":["引得车回莫认恩，却成寂寞与谁论。","到头不是君王意，羞插垂杨更傍门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-03c930d2-cb7d-493a-a5df-0ba66deace2c","tags":[]},{"id":"poem-8a5e2eb23fc1740aac821fbd","title":"过北流县八里游勾漏观留五绝句  其一","author":"李纲","dynasty":"宋","verses":["百里仙山气象雄，参差峰岫翠成丛。","云骈鹤驭今何处，丹灶依然洞穴中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-888a9d6f-1aad-4119-9385-173e7a02ce77","tags":[]},{"id":"poem-8a61da24d31a3c7116e8ed13","title":"浪淘沙·歌阕斗清新","author":"葛胜仲","dynasty":"宋","verses":["歌阕斗清新。","檀板初匀。","画堂新筑太湖滨。","好是黄花开应候，聊宴亲宾。","上客即逢辰。","况是青春。","上林开宴锡尧尊。","今夜素娥真解事，偏向人明。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-43","tags":["太湖"]},{"id":"poem-8a71c2c12fce141d3e24fe9e","title":"新秦郡松树歌","author":"王维","dynasty":"唐","verses":["青青山上松，数里不见今更逢。","不见君，心相忆，此心向君君应识。","为君颜色高且闲，亭亭迥出浮云间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-18c9eef7-5cf2-4f88-873a-e46708007e7f","tags":[]},{"id":"poem-8a76e0a09bf9cdb73f473950","title":"惜花","author":"张籍","dynasty":"唐","verses":["蒙蒙庭树花，坠地无颜色。","日暮东风起，飘扬玉阶侧。","残蘂在犹稀，青条耸复直。","为君结芳实，令君勿叹息。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d8e69d3f-323e-4e7b-a49f-86254e40c644","tags":[]},{"id":"poem-8a89314bf230b858ec25f39d","title":"奉寄中书王舍人","author":"皇甫曾","dynasty":"唐","verses":["腰金载笔谒承明，至道安禅得此生。","西掖几年纶綍贵，东山遥夜薜萝情。","风传刻漏星河曙，月上梧桐雨露清。","圣主好文谁为荐，闭门空赋子虚成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b27b13fb-d8e2-4231-a109-65068e60437d","tags":[]},{"id":"poem-8a8dc20522d6e9bdadb5900e","title":"春中田园作","author":"王维","dynasty":"唐","verses":["屋上春鸠鸣，村边杏花白。","持斧伐远扬，荷锄觇泉脉。","归燕识故巢，旧人看新历。","临觞忽不御，惆怅远行客。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b8781d18-2288-48aa-9217-75487f4f75aa","tags":["春天","田园","写景","农事"]},{"id":"poem-8a926bb43786a064bf781533","title":"滕王阁春日晚望","author":"曹松","dynasty":"唐","verses":["凌春帝子阁，偶眺日移西。","浪势平花坞，帆阴上柳堤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-0cd6589c-7911-43a4-ada3-c572208724ca","tags":["滕王阁"]},{"id":"poem-8a944761e40efcf9893b3b52","title":"七月","author":"佚名","dynasty":"先秦","verses":["七月流火，九月授衣。一之日觱发，二之日栗烈。无衣无褐，何以卒岁？","三之日于耜，四之日举趾。同我妇子，馌彼南亩。田畯至喜。","七月流火，九月授衣。春日载阳，有鸣仓庚。女执懿筐，遵彼微行，爰求柔桑。","春日迟迟，采蘩祁祁。女心伤悲，殆及公子同归。","七月流火，八月萑苇。蚕月条桑，取彼斧斨。以伐远扬，猗彼女桑。","七月鸣鵙，八月载绩。载玄载黄，我朱孔阳，为公子裳。","四月秀葽，五月鸣蜩。八月其获，十月陨萚。一之日于貉，取彼狐狸，为公子裘。","二之日其同，载缵武功。言私其豵，献豜于公。","五月斯螽动股，六月莎鸡振羽。七月在野，八月在宇，九月在户，十月蟋蟀，入我床下。","穹窒熏鼠，塞向墐户。嗟我妇子，曰为改岁，入此室处。","六月食郁及薁，七月亨葵及菽。八月剥枣，十月获稻。为此春酒，以介眉寿。","七月食瓜，八月断壶，九月叔苴，采荼薪樗。食我农夫。","九月筑场圃，十月纳禾稼。黍稷重穋，禾麻菽麦。嗟我农夫，我稼既同，上入执宫功。","昼尔于茅，宵尔索绹，亟其乘屋，其始播百谷。","二之日凿冰冲冲，三之日纳于凌阴。四之日其蚤，献羔祭韭。九月肃霜，十月涤场。","朋酒斯飨，曰杀羔羊，跻彼公堂。称彼兕觥：万寿无疆！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-153","tags":[]},{"id":"poem-8a9959a6745d2811cf26e4df","title":"奉赠宣抚孟参政二首  其一","author":"李纲","dynasty":"宋","verses":["赤子潢池学弄兵，柄臣仗节到闽城。","布宣威德雷霆奋，慰抚烝黎雨泽倾。","鏖战指踪烦妙略，凯旋铙鼓震驩声。","灵旗径向江湖去，早定艰难底太平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a1a65692-e1a5-47ff-90fc-90b78e9d7592","tags":[]},{"id":"poem-8a9d43be4cabd4be13728847","title":"赴彭州山行之作","author":"高适","dynasty":"唐","verses":["峭壁连崆峒，攒峰叠翠微。","鸟声堪驻马，林色可忘机。","怪石时侵径，轻萝乍拂衣。","路长愁作客，年老更思归。","且悦岩峦胜，宁嗟意绪违。","山行应未尽，谁与玩芳菲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f62c94f3-c060-4595-86c6-b7d32afb146d","tags":[]},{"id":"poem-8aa5ef93c95997900e36a766","title":"江儿水","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["如来证明，鉴兹邕启：我双亲在途路不知如何的？仰惟菩萨大慈悲。","(合)龙天鉴知，龙天护持，护持他赞山渡水。","(净唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5201","tags":[]},{"id":"poem-8aa9a571892403f18811eef5","title":"题招提院静照堂","author":"宋敏求","dynasty":"宋","verses":["丛林起新构，燕坐水云乡。","本自禅心静，能令世累忘。","幡花围昼永，钟梵度宵长。","归裓新篇富，笼纱映宝坊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0b7b1e72-5b78-4b39-b0ef-2d8cf5bc75f4","tags":[]},{"id":"poem-8aaa77f816c12331640c51cf","title":"遣兴二首  其二","author":"李纲","dynasty":"宋","verses":["海上归来心绪多，鬓边无那白标何。","诗情粗得江山助，酒量自因风月多。","黄卷中间笼圣哲，白云深处避干戈。","弟兄念我心应切，故向梅花岭上过。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d46de207-0dab-4264-b611-1806078ca59a","tags":[]},{"id":"poem-8aad484e50a941316fc59dce","title":"长门怨","author":"袁晖","dynasty":"唐","verses":["早知君爱歇，本自无萦妒。","谁使恩情深，今来反相误。","愁眠罗帐晓，泣坐金闺暮。","独有梦中魂，犹言意如故。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d7e52b7f-b4c8-4c4d-abf9-4ce444fe421d","tags":[]},{"id":"poem-8aaec703ffc73ec80a5297f5","title":"咏怀古迹五首 四","author":"杜甫","dynasty":"唐","verses":["蜀主窥吴幸三峡，崩年亦在永安宫。","翠华想像空山里，玉殿虚无野寺中。","古庙杉松巢水鹤，岁时伏腊走村翁。","武侯祠屋常邻近，一体君臣祭祀同。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-733afc7b-e370-4724-b755-e9342c574d22","tags":["唐诗三百首","隋・唐・五代","七言律诗","怀古","抒怀"]},{"id":"poem-8ab024a09b0172f997aa5c3e","title":"蛱蝶行","author":"卢频","dynasty":"唐","verses":["东园宫草绿，上下飞相逐。","君恩不禁春，昨夜花中宿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-53388d6f-5bc5-4836-9a5f-8aa4fddb31ac","tags":[]},{"id":"poem-8ab298bfdef27f737013604c","title":"江城子·试霜池面浅粼粼","author":"张镃","dynasty":"宋","verses":["试霜池面浅粼粼。","鹊飞晴。","远峰明。","蓬岛群仙，来过瑞云清。","龙榜当年人第一，黄叔度，是前生。","玉堂行见演丝纶。","彩毫轻。","思难停。","醉里长鲸，翻浪吸东溟。","谢女风流相称好，今母更，鬓常青。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-349","tags":[]},{"id":"poem-8ab60dc81697f3c6a602222c","title":"九辩","author":"宋玉","dynasty":"先秦","verses":["悲哉，秋之为气也！萧瑟兮草木摇落而变衰。","憭栗兮若在远行，登山临水兮送将归。","泬漻兮天高而气清，寂寥兮收潦而水清。","憯凄增欷兮，薄寒之中人，怆怳懭悢兮，去故而就新。","坎廪兮贫士失职而志不平，廓落兮羁旅而无友生，惆怅兮而私自怜！","燕翩翩其辞归兮，蝉寂漠而无声。","雁廱廱而南游兮，鹍鸡啁哳而悲鸣。","独申旦而不寐兮，哀蟋蟀之宵征。","时亹亹而过中兮，蹇淹留而无成。","悲忧穷戚兮独处廓，有美一人兮心不绎。","去乡离家兮来远客，超逍遥兮今焉薄！","专思君兮不可化，君不知兮可奈何！","蓄怨兮积思，心烦憺兮忘食事。","原一见兮道余意，君之心兮与余异。","车既驾兮朅而归，不得见兮心伤悲。","倚结軨兮长太息，涕潺湲兮下沾轼。","忼慨绝兮不得，中瞀乱兮迷惑。","私自怜兮何极？","心怦怦兮谅直。","皇天平分四时兮，窃独悲此凛秋。","白露既下百草兮，奄离披此梧楸。","去白日之昭昭兮，袭长夜之悠悠。","离芳蔼之方壮兮，余萎约而悲愁。","秋既先戒以白露兮，冬又申之以严霜。","收恢台之孟夏兮，然欿傺而沉藏。","叶烟邑而无色兮，枝烦挐而交横。","颜淫溢而将罢兮，柯仿佛而萎黄。","萷櫹椮之可哀兮，形销铄而瘀伤。","惟其纷糅而将落兮，恨其失时而无当。","揽𬴂辔而下节兮，聊逍遥以相佯。","岁忽忽而遒尽兮，恐余寿之弗将。","悼余生之不时兮，逢此世之俇攘。","澹容与而独倚兮，蟋蟀鸣此西堂。","心怵惕而震荡兮，何所忧之多方。","卬明月而太息兮，步列星而极明。","窃悲夫蕙华之曾敷兮，纷旖旎乎都房。","何曾华之无实兮，从风雨而飞飏！","以为君独服此蕙兮，羌无以异于众芳。","闵奇思之不通兮，将去君而高翔。","心闵怜之惨凄兮，愿一见而有明。","重无怨而生离兮，中结轸而增伤。","岂不郁陶而思君兮？","君之门以九重！猛犬狺狺而迎吠兮，关梁闭而不通。","皇天淫溢而秋霖兮，后土何时而得漧？","块独守此无泽兮，仰浮云而永叹！何时俗之工巧兮？","背绳墨而改错！郤骐骥而不乘兮，策驽骀而取路。","当世岂无骐骥兮，诚莫之能善御。","见执辔者非其人兮，故駶跳而远去。","凫雁皆唼夫梁藻兮，凤愈飘翔而高举。","圜凿而方枘兮，吾固知其鉏铻而难入。","众鸟皆有所登栖兮，凤独遑遑而无所集。","原衔枚而无言兮，尝被君之渥洽。","太公九十乃显荣兮，诚未遇其匹合。","谓骐骥兮安归？","谓凤皇兮安栖？","变古易俗兮世衰，今之相者兮举肥。","骐骥伏匿而不见兮，凤皇高飞而不下。","鸟兽犹知怀德兮，何云贤士之不处？","骥不骤进而求服兮，凤亦不贪餧而妄食。","君弃远而不察兮，虽原忠其焉得？","欲寂漠而绝端兮，窃不敢忘初之厚德。","独悲愁其伤人兮，冯郁郁其何极？","霜露惨凄而交下兮，心尚幸其弗济。","霰雪雰糅其增加兮，乃知遭命之将至。","原徼幸而有待兮，泊莽莽与野草同死。","原自往而径游兮，路壅绝而不通。","欲循道而平驱兮，又未知其所从。","然中路而迷惑兮，自压桉而学诵。","性愚陋以褊浅兮，信未达乎从容。","窃美申包胥之气盛兮，恐时世之不固。","何时俗之工巧兮？","灭规矩而改凿！独耿介而不随兮，原慕先圣之遗教。","处浊世而显荣兮，非余心之所乐。","与其无义而有名兮，宁穷处而守高。","食不媮而为饱兮，衣不苟而为温。","窃慕诗人之遗风兮，原讬志乎素餐。","蹇充倔而无端兮，泊莽莽而无垠。","无衣裘以御冬兮，恐溘死不得见乎阳春。","靓杪秋之遥夜兮，心缭悷而有哀。","春秋逴逴而日高兮，然惆怅而自悲。","四时递来而卒岁兮，阴阳不可与俪偕。","白日晼晚其将入兮，明月销铄而减毁。","岁忽忽而遒尽兮，老冉冉而愈弛。","心摇悦而日幸兮，然怊怅而无冀。","中憯恻之凄怆兮，长太息而增欷。","年洋洋以日往兮，老嵺廓而无处。","事亹亹而觊进兮，蹇淹留而踌躇。","何泛滥之浮云兮？","猋壅蔽此明月。","忠昭昭而原见兮，然霠曀而莫达。","原皓日之显行兮，云蒙蒙而蔽之。","窃不自聊而原忠兮，或黕点而污之。","尧舜之抗行兮，瞭冥冥而薄天。","何险巇之嫉妒兮？","被以不慈之伪名。","彼日月之照明兮，尚黯黮而有瑕。","何况一国之事兮，亦多端而胶加。","被荷裯之晏晏兮，然潢洋而不可带。","既骄美而伐武兮，负左右之耿介。","憎愠惀之修美兮，好夫人之慷慨。","众踥蹀而日进兮，美超远而逾迈。","农夫辍耕而容与兮，恐田野之芜秽。","事緜緜而多私兮，窃悼后之危败。","世雷同而炫曜兮，何毁誉之昧昧！","今修饰而窥镜兮，后尚可以窜藏。","愿寄言夫流星兮，羌倏忽而难当。","卒壅蔽此浮云，下暗漠而无光。","尧舜皆有所举任兮，故高枕而自适。","谅无怨于天下兮，心焉取此怵惕？","乘骐骥之浏浏兮，驭安用夫强策？","谅城郭之不足恃兮，虽重介之何益？","邅翼翼而无终兮，忳惛惛而愁约。","生天地之若过兮，功不成而无嶜。","原沉滞而不见兮，尚欲布名乎天下。","然潢洋而不遇兮，直怐愗而自苦。","莽洋洋而无极兮，忽翱翔之焉薄？","国有骥而不知乘兮，焉皇皇而更索？","宁戚讴于车下兮，桓公闻而知之。","无伯乐之相善兮，今谁使乎誉之？","罔流涕以聊虑兮，惟著意而得之。","纷纯纯之愿忠兮，妒被离而鄣之。","原赐不肖之躯而别离兮，放游志乎云中。","乘精气之抟抟兮，骛诸神之湛湛。","骖白霓之习习兮，历群灵之丰丰。","左朱雀之茇茇兮，右苍龙之躣躣。","属雷师之阗阗兮，通飞廉之衙衙。","前轻辌之锵锵兮，后辎乘之从从。","载云旗之委蛇兮，扈屯骑之容容。","计专专之不可化兮，原遂推而为臧。","赖皇天之厚德兮，还及君之无恙！"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-25","tags":[]},{"id":"poem-8ab9d4aaef742b5ed3a898e5","title":"江南别友人","author":"张乔","dynasty":"唐","verses":["劳生故白头，头白未应休。","阙下难孤立，天涯尚旅游。","听猨吟岛寺，待月上江楼。","醉别醒惆怅，云帆满乱流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b85e0394-7595-4662-bf30-4bbed92eb890","tags":[]},{"id":"poem-8abcc02a50e8882564d7020a","title":"生查子·小桃小杏红","author":"李石","dynasty":"宋","verses":["小桃小杏红，和雨和烟瘦。","不是点燕脂，素面偏宜酒。","也是惯伤春，可惜闲时候。","正要画眉人，与作双蛾斗。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-247","tags":[]},{"id":"poem-8acee12ec37439a705ea046d","title":"踏莎行","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["怨极愁多，歌慵笑懒，只因添个鸳鸯伴。","他乡游子不能归，高堂父母无人管。","湘浦鱼沉，衡阳雁断，音书要寄无方便。","人生光景几多时，蹉跎负却平生愿。","(生再唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5113","tags":[]},{"id":"poem-8ad5927e9920bd8a222391b8","title":"省试白云起封中","author":"陈希烈","dynasty":"唐","verses":["千年泰山顶，云起汉王封。","不作奇峰状，宁分触石容。","为霖虽易得，表圣自难逢。","冉冉排空上，依依叠影重。","素光非曳练，灵贶是从龙。","岂学无心出，东西任所从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-291e1334-8c23-495d-b9fc-3b90cd89d2d1","tags":["泰山"]},{"id":"poem-8ade2faa8388a21495fc54d4","title":"送钱给事赴虢州","author":"刘得仁","dynasty":"唐","verses":["帝心忧虢俗，暂庭辍掖垣臣。","疲瘵初承制，乡闾似得春。","化成应有瑞，位重转闻贫。","用作盐梅日，争回卧辙人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-78ac70fa-70b4-4765-81fd-843396890874","tags":[]},{"id":"poem-8adf66a950ace96f176ae6a1","title":"南乡子·云带雨","author":"李珣","dynasty":"五代","verses":["云带雨，浪迎风，钓翁回棹碧湾中。","春酒香熟鲈鱼美，谁同醉？","缆却扁舟篷底睡。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-30","tags":[]},{"id":"poem-8ae88200f841ab6a6147be02","title":"浣溪沙·花想仪容柳想腰","author":"向子𬤇","dynasty":"宋","verses":["花想仪容柳想腰。","融融曳曳一团娇。","绮罗丛里最妖娆。","歌罢碧天零影乱，舞时红袖雪花飘。","几回相见为魂销。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-791","tags":[]},{"id":"poem-8aeb28703b0072a4ff079384","title":"和蒋进士秋日","author":"李咸用","dynasty":"唐","verses":["晚雨霏微思杪秋，不堪才子尚羇游。","尘随别骑东西急，波促年华日夜流。","凉月云开光自远，古松风在韵难休。","男儿但得功名立，纵是深恩亦易酬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-432e8516-22fb-41fa-b79c-5b3e5ce897ef","tags":[]},{"id":"poem-8aebf80f011140723155e8d9","title":"临江仙·幽闺小槛春光晚","author":"顾敻","dynasty":"五代","verses":["幽闺小槛春光晚，柳浓花淡莺稀。","旧欢思想尚依依，翠颦红敛，终日损芳菲。","何事狂夫音信断，不如梁燕犹归。","画意深处麝烟微，屏虚枕冷，风细雨霏霏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-32","tags":[]},{"id":"poem-8af9a50898e3f2b95c655023","title":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","author":"刘长卿","dynasty":"唐","verses":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fdc07d9f-95b8-45f7-b1b3-9d272b3416a4","tags":["唐诗三百首","长江","怀古","秋天","五言律诗"]},{"id":"poem-8b1602dae9cc9b473b907cff","title":"奉酬睢阳李太守","author":"高适","dynasty":"唐","verses":["公族称王佐，朝经允帝求。","本枝疆我李，盘石冠诸刘。","礼乐光辉盛，山河气象幽。","系高周柱史，名重晋阳秋。","华省膺推择，青云宠宴游。","握兰多具美，前席有嘉谋。","赋得黄金赐，言皆白璧酬。","着鞭驱驷马，操刃解全牛。","出镇兼方伯，承家复列侯。","朝瞻孔北海，时用杜荆州。","广固才登陟，毘陵忽阻修。","三台冀入梦，四岳尚分忧。","郡邑连京口，山川望石头。","海门当建节，江路引鸣驺。","俗见中兴理，人逢至道休。","先移白额横，更息赭衣偷。","梁国歌来晚，徐方怨不留。","岂伊齐政术，将以变浇浮。","讼简知能吏，刑宽察要囚。","坐堂风偃草，行县雨随辀。","地是蒙庄宅，城遗阏伯丘。","孝王余井径，微子故田畴。","冬至招摇转，天寒䗖𬟽收。","猿岩飞雨雪，兔苑落梧楸。","列戟霜侵户，褰帏月在钩。","好贤常解榻，乘兴每登楼。","逸足横千里，高谈注九流。","诗题青玉案，衣赠黑貂裘。","穷巷轩车静，闲斋耳目愁。","未能方管乐，翻欲慕巢由。","讲德良难敌，观风岂易俦。","寸心仍有适，江海一扁舟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-4506e47c-d89b-45ca-a9c5-8f9c457409b6","tags":[]},{"id":"poem-8b1f8c7225e6915461f91c43","title":"偈颂十四首  其一三","author":"释印肃","dynasty":"宋","verses":["一轮秋月映悲风，数和松音标此意。","因缘究竟莫劳神，时节到来无不备。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-64190703-f162-4539-b8a8-2d1b5efbe656","tags":[]},{"id":"poem-8b215505b47fb18a732c0c26","title":"西湖","author":"苏轼","dynasty":"宋","verses":["毕竟西湖六月中，风光不与四时同。","接天莲叶无穷碧，映日荷花别样红。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-西湖","tags":[]},{"id":"poem-8b2343308e5af06fa15d7565","title":"咏史诗 居延","author":"胡曾","dynasty":"唐","verses":["漠漠平沙际碧天，问人云此是居延。","停骖一顾犹魂断，苏武争禁十九年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-046d4c27-7171-4f85-88e7-5923a7808afa","tags":[]},{"id":"poem-8b29580e36ffe8cb06dd9c37","title":"寄峡州韦郎中","author":"李涉","dynasty":"唐","verses":["年过五十鬓如丝，不必前程更问师。","幸得休耕乐尧化，楚山深处最相宜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-470df489-6f73-41f6-97b9-f5e74d9a8c7d","tags":[]},{"id":"poem-8b3348a246fec3322d31ba05","title":"郊庙歌辞 武后大享拜洛乐章 德和","author":"不详","dynasty":"唐","verses":["夕惕司龙契，晨兢当凤扆。","崇儒习旧规，偃伯循先旨。","绝壤飞冠盖，遐区丽山水。","幸承三圣余，忻属千年始。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a69e1314-b376-449b-9db5-58233b8c54d0","tags":[]},{"id":"poem-8b352588db14c41f0fd5f76d","title":"杏园","author":"徐夤","dynasty":"唐","verses":["杏苑箫声好醉乡，春风嘉宴更无双。","凭谁为谑穆天子，莫把瑶池并曲江。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-e033b3ed-18e6-49e0-80fe-c3d9889a1eae","tags":[]},{"id":"poem-8b35c8f41226edf1d04e3ff0","title":"次赵有翼简徐圣可元韵","author":"曾协","dynasty":"宋","verses":["已向幽居赋晚晴，欲经绝壁访神清。","不忧五柳荒松菊，敢叹三闾带杜蘅。","=无风月三千首，赖有丝桐一再行。","谁似孔庭能父子，继挥高韵思如倾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-fc3a6d26-2d13-432d-86a4-ab073affadae","tags":[]},{"id":"poem-8b37abf9dff6150b47bcbe9b","title":"玉簪花和希纯  其八","author":"刘跂","dynasty":"宋","verses":["蓝田故有他山错，瑶旆琼旒碧玉干。","左紫姚黄满金谷，野人留取伴鸡冠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-db7039e3-cb38-4141-bbb6-38031d926c07","tags":[]},{"id":"poem-8b405d21328cd491093bda81","title":"禁中春松","author":"陆贽","dynasty":"唐","verses":["阴阴清禁里，苍翠满春松。","雨露恩偏近，阳和色更浓。","高枝分晓日，虚吹杂宵钟。","香助𬬻烟远，形疑盖影重。","愿符千载寿，不羡五株封。","傥得回天眷，全胜老碧峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f0a74e24-e84f-48cd-a77c-cfdc6fa9a5fd","tags":[]},{"id":"poem-8b42898d3dd47d97db4b1421","title":"大隐坊 章仇将军良弃功守贫","author":"孟郊","dynasty":"唐","verses":["饮君江海心，讵能辨浅深。","挹君山岳德，谁能齐嵚岑。","东海精为月，西岳气凝金。","进则万景昼，退则群物阴。","我欲荐此言，天门峻沈沈。","风飙亦感激，为我飕飗吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b88f75dc-df70-45f9-87c9-11713eed0137","tags":["华山"]},{"id":"poem-8b45cff0c3ecf49ecd0cbd85","title":"示执坐禅者颂","author":"省澄","dynasty":"唐","verses":["大道分明绝点尘，何须长坐始相亲。","遇缘傥解无非是，处愦那能有故新。","散诞肯齐支遁侣，逍遥曷与慧休邻。","或游泉石或阛阓，可谓烟霞物外人。","（按：《闽诗录丙集》卷十九录此诗作：「大道分明绝点尘，何须枯坐始相亲。","杖藜日涉溪山趣，便是烟霞物外人。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-11d108f2-012b-471b-9b8b-7779fa2d7d09","tags":[]},{"id":"poem-8b4610670cfeb08323000ae9","title":"十八郎殿下又送偈上国师兼请和师乃答之","author":"神晏","dynasty":"唐","verses":["建化开遮假立名，无名之说亦难停。","其中荐得非关识，朗月当空不自明。","北京秀长称为泽，南派传宗祖讳能。","黄卷暂诠呼作性，教外须参有别行。","（以上八首均见《古尊宿语录》卷三七《鼓山先兴圣国师和尚法堂玄要广集》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c03f6219-ec22-4767-8f7c-37d54be405e0","tags":[]},{"id":"poem-8b52524fbbb78b7d1cd35d19","title":"题化城寺","author":"应物","dynasty":"唐","verses":["平高选处创莲宫，一水萦流处处通。","画阁昼开迟日畔，禅房夜掩碧云中。","平川不见龙行雨，幽谷遥闻虎啸风。","偶与游人论法要，真元浩浩理无穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-aee480d4-8058-4cfa-8a2a-639b70a39deb","tags":[]},{"id":"poem-8b583c656831d876e5588949","title":"宛陵馆冬青树","author":"赵嘏","dynasty":"唐","verses":["碧树如烟覆晚波，清秋欲尽客重过。","故园亦有如烟树，鸿雁不来风雨多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c78d4a35-d541-449a-a7e0-373adff95945","tags":[]},{"id":"poem-8b5efcd4d04bafb466ce2ea5","title":"后庭花·景阳钟动宫莺啭","author":"孙光宪","dynasty":"五代","verses":["景阳钟动宫莺啭，露凉金殿。","轻飙吹起琼花旋，玉叶如剪。","晚来高阁上，珠帘卷，见坠香千片。","修蛾慢脸陪雕辇，后庭新宴。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-9","tags":[]},{"id":"poem-8b5f64f8c0d5dcdfe9ebba81","title":"自上封下福岩道旁访李邺侯书堂山路榛合不可往矣","author":"张栻","dynasty":"宋","verses":["石壁巉岩路已荒，人言相国旧书堂。","临机自古多遗恨，妙策当年取范阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5a960bd6-3051-4aee-90b4-19505688d3ce","tags":[]},{"id":"poem-8b639db9ad6ececf2c01e49c","title":"水底鱼","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［生上］天下贤良，赴选临帝乡。","白衣卿相，暮登天子堂。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8138","tags":[]},{"id":"poem-8b69d95b55f7dda2077bf686","title":"送友人及第后归台州","author":"贯休","dynasty":"唐","verses":["得桂为边辟，翩翩颇合宜。","嫖姚留不住，昼锦已归迟。","岛侧花藏虎，湖心浪撼棋。","终期华顶下，共礼渌身师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6472c949-4888-4320-9fb5-958fc3d5d01b","tags":[]},{"id":"poem-8b7766510469a4bcc74faa9e","title":"更依前韵上献恶诗搜吟虽罄于短才歌咏宁穷于盛美","author":"李昉","dynasty":"宋","verses":["茂陵词客马相如，贮蓄胸中万卷余。","闲坐小斋惟看画，旋分清俸只抄书。","槛花灼灼韶光盛，庭竹森森翠影疏。","晨入蓬山暮归去，到归多是闭门居。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-a795e158-db36-403c-b738-dc2ca799f4d9","tags":[]},{"id":"poem-8b800af8cff7bef681d9b4f2","title":"劝金船·流泉宛转双开窦","author":"张先","dynasty":"宋","verses":["流泉宛转双开窦。","带染轻纱皱。","何人暗得金船酒。","拥罗绮前后。","绿定见花影，并照与、艳妆争秀。","行尽曲名，休更再歌杨柳。","光生飞动摇琼甃。","隔障笙箫奏。","须知短景欢无足，又还过清昼。","翰阁迟归来，传骑恨、留住难久。","异日凤凰池上，为谁思旧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-414","tags":[]},{"id":"poem-8b87220efd910476600a57d2","title":"秋蕊香·帘幕疏疏风透","author":"张耒","dynasty":"宋","verses":["帘幕疏疏风透。","一线香飘金兽。","朱阑倚遍黄昏后。","廊上月华如昼。","别离滋味浓于酒。","著人瘦。","此情不及墙东柳。","春色年年如旧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-350","tags":[]},{"id":"poem-8b898fe862e51bbe250e1452","title":"商山道中","author":"赵嘏","dynasty":"唐","verses":["和如春色净如秋，五月商山是胜游。","当昼火云生不得，一溪萦作万重愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-ea49850f-bc2d-492a-96d5-92bee9655ba5","tags":[]},{"id":"poem-8b8c5788a6677cd25ab58772","title":"连州吟 三","author":"孟郊","dynasty":"唐","verses":["朝亦连州吟，暮亦连州吟。","连州果有信，一纸万里心。","开缄白云断，明月堕衣襟。","南风嘶舜琯，苦竹动猿音。","万里愁一色，潇湘雨淫淫。","两劒忽相触，双蛟恣浮沈。","鬬水正回斡，倒流安可禁。","空愁江海信，惊浪隔相寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b6c96e59-7b85-441f-9dd6-eccdf167757c","tags":[]},{"id":"poem-8b8e79d57e5d734770949d04","title":"春晓闻众禽声有感","author":"李纲","dynasty":"宋","verses":["春山苍莽天欲明，枕上静听春禽鸣。","雏莺初啭正调舌，姹娅乍闻三两声。","不如归去意良切，脱却泼袴何由行。","愁人最是断消息，姑恶更觉声娇狞。","布谷催耕雨才足，鹁鸠唤妇远将晴。","其余不复识名字，雅音幽韵如簧笙。","天公怜我太寂寞，故遣尤物怡吾情。","鸾歌凤舞未可见，候虫时鸟聊嘤嘤。","我生半世困漂泊，巧言谗谤饱所经。","杜门却扫与世绝，欲窒两牖忘雷霆。","尔声虽好太饶舌，逼耳颇似虚弦惊。","就中提壶可人意，劝我沽酒花间倾。","心怀百忧只欲睡，更愿常醉不用醒。","落花芳草正可藉，玉山自倒知谁令。","乌啼鹊噪错昏昼，燕雀啾唧环簷楹。","从教一一恣嘲弄，吾方深入无何庭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-4741fa84-baa6-4741-92b4-a4682135b6d8","tags":[]},{"id":"poem-8b91343a9bc225081e8e323a","title":"将至妙喜寺","author":"徐凝","dynasty":"唐","verses":["清风袅袅越水陂，远树苍苍妙喜寺。","自有车轮与马蹄，未曾到此波心地。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ecbc2667-468b-4189-9f75-5f622d8ebb73","tags":[]},{"id":"poem-8b934221a6880867b5473e76","title":"南柯子・南歌子·共禀阴阳数","author":"曾觌","dynasty":"宋","verses":["共禀阴阳数，谁知造化工。","安闲百计总输公。","掩映芙蓉花径、郡城东。","风月三秋兴，尊罍一笑同。","新词佳丽见情通。","更唤雪儿、低唱慰衰容。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-408","tags":[]},{"id":"poem-8b962c36845d899c14a67c11","title":"题金华宫","author":"蜀太后徐氏","dynasty":"唐","verses":["再到金华顶，玄都访道回。","云披分景象，黛锁显楼台。","雨涤前山净，风吹去路开。","翠屏夹流水，何必羡蓬莱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-15bac88f-aae3-4249-861e-7d42a2120302","tags":[]},{"id":"poem-8b9a18d592e7213f11be9f83","title":"象骨山颂","author":"道怤","dynasty":"唐","verses":["密密谁知要，明明许也无。","森萝含本性，山岳尽如如。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-11a36d5e-55b9-4004-8527-8c5b831f9be4","tags":[]},{"id":"poem-8b9b338516e74d6ac5ed10a8","title":"答五陵太守","author":"王昌龄","dynasty":"唐","verses":["仗剑行千里，微躯敢一言。","曾为大梁客，不负信陵恩。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-答五陵太守","tags":[]},{"id":"poem-8b9c7f3a4d35f7625b77cca3","title":"忆昔二首 一","author":"杜甫","dynasty":"唐","verses":["忆昔先皇巡朔方，千乘万骑入咸阳。","阴山骄子汗血马，长驱东胡胡走藏。","邺城反复不足怪，关中小儿坏纪纲，张后不乐上为忙。","至今今上犹拨乱，劳身焦思补四方。","我昔近侍叨奉引，出兵整肃不可当。","为留猛士守未央，致使岐雍防西羌。","犬戎直来坐御床，百官跣足随天王愿见北地傅介子，老儒不用尚书郎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5cee205e-5c59-46e5-b060-9b0916c64a3f","tags":[]},{"id":"poem-8b9e669a50a28442dc523f28","title":"定西番·细雨晓莺春晚","author":"温庭筠","dynasty":"唐","verses":["细雨晓莺春晚。","人似玉，柳如眉，正相思。","罗幕翠帘初卷，镜中花一枝。","肠断塞门消息，雁来稀。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-28","tags":[]},{"id":"poem-8ba9b804abbff6d50a29f747","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["金梧飘坠，纨扇懒挥。","牛女会佳期，只见丹桂飘金蕊，风传香韵美。","遥望着碧天如洗，遥望着碧天如洗，万里月扬辉。","夫人，我和你一似皓月澄清团圆到底。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8970","tags":[]},{"id":"poem-8bb4142fd74c9efc60738262","title":"丽人行","author":"杜甫","dynasty":"唐","verses":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有，翠微㔩叶垂鬓唇。","背后何所见，珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫驼之峰出翠釜，水精之盘行素鳞。","犀箸厌饫久未下，銮刀缕切空纷纶。","黄门飞鞚不动尘，御厨络绎送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-370b53ae-949e-45cf-92b0-3aca072c1b86","tags":["杂曲歌辞","唐诗三百首","乐府","讽刺","咏叹"]},{"id":"poem-8bb5b15229678a165e5e9cdf","title":"歌者十二首 九","author":"司空图","dynasty":"唐","verses":["白云深处寄生涯，岁暮生情赖此花。","蜂蝶绕来忙绕袖，似知教折送邻家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-98efd3fa-7d36-4b52-9025-98a1f819a074","tags":[]},{"id":"poem-8bc2395305a83780ab8f968a","title":"问寇校书双谿","author":"王维","dynasty":"唐","verses":["君家少室西，为复少室东。","别来几日今春风，新买双谿定何似。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7ce06de3-1f97-464c-aac1-8dd5653e84f6","tags":[]},{"id":"poem-8bc553324c9caf367fadf4a5","title":"古从军","author":"王建","dynasty":"唐","verses":["汉家逐单于，日没处河曲。","浮云道旁起，行子车下宿。","枪城围鼓角，毡帐依山谷。","马上悬壶浆，刀头分颊肉。","来时高堂上，父母亲结束。","回面不见家，风吹破衣服。","金疮在肢节，相与拔箭镞。","闻道西凉州，家家妇女哭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4f447572-d25c-4898-a1c0-0f2f1a8194e8","tags":[]},{"id":"poem-8bc820bf8af1cc957b24413c","title":"鹧鸪天·背立盈盈故作羞","author":"纳兰性德","dynasty":"清","verses":["背立盈盈故作羞，手挼梅蕊打肩头。","欲将离恨寻郎说，待得郎来恨却休。","云淡淡，水悠悠。","一声横笛锁空楼。","何时共泛春溪月，断岸垂杨一叶舟。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-106","tags":[]},{"id":"poem-8bce11da8e0a7347231c1ba6","title":"投魏博李相国三十二韵","author":"张祜","dynasty":"唐","verses":["天意兆升平，忠良自间生。","二年移四镇，一夜破重城。","白刃来临敌，青油引出京。","指途谙老马，望海哂长鲸。","国用鞭头筭，军机帐下萌。","王师初戮力，贼将首推诚。","鼎鼐传家世，藩隅易弟兄。","风云将气合，才命与时幷。","咳唾收齐土，疮痍肓蔡甿。","指㧑从上策，谈笑赖高情。","发号方回踵，归农务散兵。","紫微才近侍，彤矢又专征。","曲直须绳准，幽深藉镜明。","晓江流汗漫，秋华耸峥嵘。","士勇思陈力，儿啼畏道名。","文王开卦兆，武帝下星精。","远寄恩弥厚，深欺敌不勍。","俭风敦制度，和气茂逢迎。","画障朱轩设，蛮刀粉壁横。","木鱼连𬬭动，金兽齿环狞。","舞席宫鬃出，宾盘海馔盈。","绣蹄红毬卧，花领紫绦萦。","鹓鹭初移府，熊罴夜烈营。","（「烈」，严疑当作「列」。","）济河无反顾，当阵必前行。","野迥朱旗卜，霜干翠幕轻。","角吹寒日色，枪揭暑雷声。","宁越身犹贱，冯煖胆未呈。","贵门心强迹，贤路力何争。","閟手从抛劒，愁肠却赖觥。","宁依刘表死，不接贾充荣。","阻辙羞偏毂，蟠泥渴一泓。","应怜望尘眼，歧路拜双旌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-bb69e2a6-91d2-4816-bab1-40c9fab7fa5b","tags":[]},{"id":"poem-8bce406b692b19f47b636d12","title":"嵩山十志十首 其七","author":"卢鸿一","dynasty":"唐","verses":["灵矶盘礴兮溜奔错漱，冷风兮镇冥壑。","研苔滋兮泉珠洁，一饮一憩兮气想灭。","磷涟清淬兮涤烦矶，灵仙境兮仁智归。","中有琴兮徽以玉，峨峨汤汤兮弹此曲，寄声知音兮同所欲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c06b734d-acb4-4a0a-ba70-e9ba22f1678f","tags":[]},{"id":"poem-8bcfa9f34a925b7fa2f0455a","title":"宫词  其一一","author":"张公庠","dynasty":"宋","verses":["年华先到未央宫，嬉赏班班四序中。","潇洒梅花元耐雪，轻狂柳絮不嫌风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-9f0bb6b2-9025-42db-bc31-03138af344a2","tags":[]},{"id":"poem-8bd4abc0a565fa82386562c4","title":"遣怀","author":"杜甫","dynasty":"唐","verses":["昔我游宋中，惟梁孝王都。","名今陈留亚，剧则贝魏俱。","邑中九万家，高栋照通衢。","舟车半天下，主客多欢娱。","白刃讐不义，黄金倾有无。","杀人红尘里，报答在斯须。","忆与高李辈，论交入酒垆。","两公壮藻思，得我色敷腴。","气酣登吹台，怀古视平芜。","芒砀云一去，雁鹜空相呼。","先帝正好武，寰海未凋枯。","猛将收西域，长戟破林胡。","百万攻一城，献捷不云输。","组练弃如泥，尺土负百夫。","拓境功未已，元和辞大炉。","乱离朋友尽，合沓岁月徂。","吾衰将焉托，存殁再呜呼。","萧条益堪媿，独在天一隅。","乘黄已去矣，凡马徒区区。","不复见颜鲍，系舟卧荆巫。","临餐吐更食，常恐违抚孤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f5003828-ec14-49f6-a2b4-9eb6ce67a9d8","tags":[]},{"id":"poem-8bd5055016c75d9487dbecec","title":"成名年献座主仆射兼呈同年","author":"赵嘏","dynasty":"唐","verses":["拂烟披月羽毛新，千里初辞九陌尘。","曾失玄珠求[象罔]，不将双耳负伶伦。","贾嵩词赋相如手，杨乘歌篇李白身。","除却今年仙侣外，堂堂又见两三春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-275b88fc-4319-4748-a9e8-b763024d50e2","tags":[]},{"id":"poem-8be40b184e33b41d96f8bbc9","title":"罔象得玄珠","author":"张籍","dynasty":"唐","verses":["赤水今何处，遗珠已渺然。","离娄徒肆目，罔象乃通玄。","皎洁因成性，圆明不在泉。","暗中看夜色，尘外照晴田。","无胫真难掬，怀疑实易迁。","今朝搜择得，应免媚晴川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-79f27efe-fb2a-4e22-b7ec-a30d9a0cfd1b","tags":[]},{"id":"poem-8be53488132aaca9ae41352e","title":"奉和圣制荅张说扈从南出雀鼠谷之作","author":"袁晖","dynasty":"唐","verses":["魏国山河险，周王警跸回。","九旗云际出，万骑谷中来。","石路行将尽，烟郊望忽开。","赏矜垂柳报，春畏落花催。","兴逸横汾什，恩褒作颂才。","小臣瞻日月，延首咏康哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-29b67fd8-ac8b-4e91-909e-b92ef44c66d1","tags":[]},{"id":"poem-8bf97acb779c9852a0cb0615","title":"醉桃源・阮郎归·鸳鸯浓睡碧溪沙","author":"方千里","dynasty":"宋","verses":["鸳鸯浓睡碧溪沙。","荷花深处家。","快风收电掣金蛇。","凉波流素华。","吴国艳，楚宫娃。","红潮连翠霞。","坐来忽忽烛光斜。","城头闻乱鸦。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-540","tags":[]},{"id":"poem-8bfc577da5d80b76070a6df8","title":"燕归梁·风摆红藤卷绣帘","author":"欧阳修","dynasty":"宋","verses":["风摆红藤卷绣帘。","宝鉴慵拈。","日高梳洗几时忺。","金盆水、弄纤纤。","髻云谩亸残花淡，和娇媚、瘦岩岩。","离情更被宿酲兼。","空惹得、病厌厌。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-792","tags":[]},{"id":"poem-8bfe11e63815f91450d1b217","title":"和林成之五题 西邻","author":"苏颂","dynasty":"宋","verses":["西邻击鼓北邻听，饮马持戈密相应。","一朝奋跃事争锋，朔气充盈夸战胜。","中原太平日已久，刃顿兵闲空细柳。","二疆款附岁奔驰，捆载金缯萃渊薮。","饫肥服煖四十年，但欲包藏忘德厚。","谋夫愤愤壮士忧，屡献忠言曾苦口。","庙堂尚论正无为，肯向平时议攻守。","朔方三十有六郡，户敛家输佐行阵。","非无硕画破妖巢，直遣万里威棱振。","皇天爱人犹赤子，纵欲敺之言亦讱。","彼方束手听誓盟，重获岁时贽琛賮。","斯民怀德乐休兵，戍卒归来解锋刃。","皆言邻徼复清夷，嗟哉异类终难信。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-278f87ec-f5f4-4b7b-94fa-1510a4fa3e86","tags":[]},{"id":"poem-8c08cee7632a0ca12f43f5aa","title":"锦瑟","author":"李商隐","dynasty":"唐","verses":["锦瑟无端五十弦，一弦一柱思华年。","庄生晓梦迷蝴蝶，望帝春心托杜鹃。","沧海月明珠有泪，蓝田日暖玉生烟。","此情可待成追忆，只是当时已惘然。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e0eb3016-9288-4dc0-9257-3de36e5ad73c","tags":["唐诗三百首","思念","七言律诗","抒情","爱情"]},{"id":"poem-8c08ceeeb5ffc7357545bdb1","title":"早春归山中旧居","author":"薛能","dynasty":"唐","verses":["茫茫驱匹马，归处是荒榛。","猨迹破庭雪，鼠踪生甑尘。","开门冲网断，扫叶放苔匀。","为惜诗情错，应难致此身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-fd8b60f4-8ffd-4a3b-b96a-4ea00f11f422","tags":[]},{"id":"poem-8c0ab5aa63608bce59be8c8e","title":"江梅引・江城梅花引·重闺佳丽最怜梅","author":"洪皓","dynasty":"宋","verses":["重闺佳丽最怜梅。","牖春开。","学妆来。","争粉翻光、何遽落梳台。","笑坐雕鞍歌古曲，催玉柱，金卮满，劝阿谁。","贪为结子藏暗蕊。","敛蛾眉，隔千里。","旧时罗绮。","已零散、沈谢双飞。","不见娇姿、真悔著单衣。","若作和羹休讶晚，堕烟雨，任春风，片片吹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-907","tags":[]},{"id":"poem-8c12c520479b15c751e5df61","title":"闲居作五首 其四","author":"张祜","dynasty":"唐","verses":["闷看垂簷雨，闲寻小院芳。","壁泥根长麦，篱柱叶生杨。","旋碾新茶试，生开嫩酒尝。","看看花渐老，无复滞春光。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-60aa5fb8-0040-4d53-8807-17719f2db621","tags":[]},{"id":"poem-8c197c679c9af60a2e779199","title":"九日陪皇甫使君泛江宴赤岸亭","author":"畅当","dynasty":"唐","verses":["羁旅逢佳节，逍遥忽见招。","同倾菊花酒，缓櫂木兰桡。","平楚堪愁思，长江去寂寥。","猿啼不离峡，滩沸镇如潮。","举目关山异，伤心乡国遥。","徒言欢满座，谁觉客魂消。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-bbe5917e-3b2f-45ac-b458-bcbf662e1aad","tags":["长江"]},{"id":"poem-8c217f68864c7f5130d826ee","title":"古扇","author":"项斯","dynasty":"唐","verses":["昨日裁成夺夏威，忽逢秋节便相违。","寒尘妬尽秦王女，凉殿恩随汉主妃。","似月旧临红粉面，有风休动麝香衣。","千年萧瑟关人事，莫语当时掩泪归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-94f889e1-3648-4911-aadf-44158e6b2469","tags":[]},{"id":"poem-8c221d9a4523021310ec8863","title":"偶然五首 五","author":"皎然","dynasty":"唐","verses":["真隐须无矫，忘名要似愚。","只将两条事，空却汉潜夫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f7dd7349-0416-4fc8-b53d-0852f0203054","tags":[]},{"id":"poem-8c2597f07d2a736b59b6797a","title":"赠吏部孙员外济","author":"张谔","dynasty":"唐","verses":["天子爱贤才，星郎入拜来。","明光朝半下，建礼直初回。","名带含香发，文随绮幕开。","披云自有镜，从此照仙台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b9b88e5e-5909-4b37-9c3d-8a5c3641f396","tags":[]},{"id":"poem-8c2b04553e35017949b2024d","title":"女冠子·春山夜静","author":"李珣","dynasty":"五代","verses":["春山夜静，愁闻洞天疏磬。","玉堂虚，细雾垂珠佩，轻烟曳翠裙。","对花情脉脉，望月步徐徐。","刘阮今何处？绝来书。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-36","tags":[]},{"id":"poem-8c2f75797993a6c689c0f2bb","title":"金铜仙人辞汉歌","author":"李贺","dynasty":"唐","verses":["茂陵刘郎秋风客，夜闻马嘶晓无迹。","画栏桂树悬秋香，三十六宫土花碧。","魏官牵车指千里，东关酸风射眸子。","空将汉月出宫门，忆君清泪如铅水。","衰兰送客咸阳道，天若有情天亦老。","携盘独出月荒凉，渭城已远波声小。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-56f01a7d-2d53-4191-b6e4-7cc94fa76515","tags":["隋・唐・五代","怀古","离别","感伤"]},{"id":"poem-8c3119e9785a6347270e1604","title":"襄阳曲二首 二","author":"崔国辅","dynasty":"唐","verses":["少年襄阳地，来往襄阳城。","城中轻薄子，知妾解秦筝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fa4076ef-ddda-4c26-ae49-657fba2c3f86","tags":[]},{"id":"poem-8c4a584d0962e216ab5fdf5e","title":"谢新恩·秦楼不见吹箫女","author":"李煜","dynasty":"五代","verses":["秦楼不见吹箫女，空馀上苑风光。","粉英含蕊自低昂。","东风恼我，才发一衿香。","琼窗梦醒留残日，当年得恨何长。","碧栏杆外映垂杨。","暂时相见，如梦懒思量。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-30","tags":[]},{"id":"poem-8c4bd4f2156ef95fc8fe603b","title":"南歌子·手里金鹦鹉","author":"温庭筠","dynasty":"唐","verses":["手里金鹦鹉，胸前绣凤凰。","偷眼暗形相，不如从嫁与，作鸳鸯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-37","tags":[]},{"id":"poem-8c5ec7b428d695f66572a066","title":"海上得孔雀六鹦鹉十余携归遗童稚辈戏成二绝句  其二","author":"李纲","dynasty":"宋","verses":["绿衣绀趾已能飞，学语交交末转时。","不是蓬莱花鸟使，携归聊与调群儿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-aa3ed2df-6753-4b7f-a2b6-eeb58e34950e","tags":[]},{"id":"poem-8c75e41d433dff288383d3bb","title":"奉和圣制送张说上集贤学士赐宴","author":"裴漼","dynasty":"唐","verses":["问道图书盛，尊儒礼教兴。","石渠因学广，金殿为贤升。","日月恩光照，风云宠命膺。","谋谟言可范，舟檝事斯凭。","宴喜明时洽，光辉湛露凝。","大哉尧作主，天下颂歌称。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-92f7144c-b226-40e5-a28b-ae7789ab8c0c","tags":[]},{"id":"poem-8c815e4d3634c5472e5ddc62","title":"早过湖","author":"释居简","dynasty":"宋","verses":["唤得航船傍采菱，柳桥竹榭曙烟深。","船头惊起蜻蜓睡，欲立还飞到涌金。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-5124d4e9-ef57-42fb-b61e-518794d75194","tags":[]},{"id":"poem-8c8359be701142ea6b542f52","title":"田家春望","author":"高适","dynasty":"唐","verses":["出门何所见，春色满平芜。","可叹无知己，高阳一酒徒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-992319d5-c110-4285-9302-cb6d8144bd85","tags":[]},{"id":"poem-8c86216a89b9241bba9dd942","title":"奉试咏青","author":"荆冬倩","dynasty":"唐","verses":["路辟天光远，春还月道临。","草浓河畔色，槐结路边阴。","未映君王史，先标胄子襟。","经明如可拾，自有致云心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f558fbb7-b8d7-413b-bc61-fbafc0b99404","tags":[]},{"id":"poem-8c8f695beae8b77b03ea4cf6","title":"喜入兰陵望紫阁峰呈宣上人","author":"李益","dynasty":"唐","verses":["薙草开三径，巢林喜一枝。","地宽留种竹，泉浅欲开池。","紫阁当疎牖，青松入坏篱。","从今安僻陋，萧相是吾师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-566b6a8b-7a12-4b35-a277-f9b4a530c908","tags":[]},{"id":"poem-8c90b758fac28bab8c609771","title":"减字木兰花·杏花零乱","author":"葛胜仲","dynasty":"宋","verses":["杏花零乱。","拟把百觚来判断。","病卧漳滨。","不见枝头闹小春。","吾衰老矣。","一醉花前犹不遂。","情绪厌厌。","虚度韶光又一年。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-22","tags":[]},{"id":"poem-8caf61051393accf55150d43","title":"听安万善吹觱篥歌","author":"李颀","dynasty":"唐","verses":["南山截竹为觱篥，此乐本自龟兹出。","流传汉地曲转奇，凉州胡人为我吹。","傍邻闻者多叹息，远客思乡皆泪垂。","世人解听不解赏，长飙风中自来往。","枯桑老柏寒飕飗，九雏鸣凤乱啾啾。","龙吟虎啸一时发，万籁百泉相与秋。","忽然更作渔阳掺，黄云萧条白日暗。","变调如闻杨柳春，上林繁花照眼新。","岁夜高堂列明烛，美酒一杯声一曲。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2d66a9e4-7b4d-4be4-91fd-6a4b2cd8817b","tags":["唐诗三百首","音乐","七言古诗"]},{"id":"poem-8cbdb3fce9e542342d93f659","title":"行路难 二","author":"贯休","dynasty":"唐","verses":["不会当时作天地，刚有多般愚与智。","到头还用真宰心，何如上下皆清气。","大道冥冥不知处，那堪顿得羲和辔。","义不义兮仁不仁，拟学长生更容易。","负心为罏复为火，缘木求鱼应且止。","君不见烧金炼石古帝王，鬼火荧荧白杨里。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-eca50797-22fc-4805-8db6-96546f8383eb","tags":[]},{"id":"poem-8cc21aec86763cca791d0bdc","title":"句  其一","author":"徐铉","dynasty":"宋","verses":["一夜黄星照官渡，本初何面见田丰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b56ea48b-10b8-44c9-9d35-a05cc2bc0cbe","tags":[]},{"id":"poem-8cc3de4a6d4a262ddf676046","title":"如梦令·黄叶青苔归路","author":"纳兰性德","dynasty":"清","verses":["黄叶青苔归路，屧粉衣香何处。","消息竟沉沉，今夜相思几许。","秋雨，秋雨，一半因风吹去。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-55","tags":[]},{"id":"poem-8cc9d8abcf6d596893e12b63","title":"浣溪沙·叶底青青杏子垂","author":"欧阳修","dynasty":"宋","verses":["叶底青青杏子垂。","枝头薄薄柳绵飞。","日高深院晚莺啼。","堪恨风流成薄幸，断无消息道归期。","托腮无语翠眉低。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-741","tags":[]},{"id":"poem-8ccc06cf46666c0071e8e65c","title":"答司马承祯上劒镜","author":"明皇帝","dynasty":"唐","verses":["宝照含天地，神劒合阴阳。","日月丽光景，星斗裁文章。","写鉴表容质，佩服为身防。","从兹一赏玩，永德保龄长。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-1ea9b354-24bc-497a-a8fb-0e83e0a00c9f","tags":[]},{"id":"poem-8ccdb84b7fbf51e82ea205cb","title":"失调名·挂天师","author":"魏掞之","dynasty":"宋","verses":["挂天师，撑著眼，直下觑。","骑个生狞大艾虎。","闲神浪鬼，辟惵他方远方，大胆底，更敢来、上门下户。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-583","tags":[]},{"id":"poem-8cd1f8b2d50e13bbc6405db8","title":"尉迟杯·隋堤路","author":"周邦彦","dynasty":"宋","verses":["隋堤路。","渐日晚、密霭生深树。","阴阴淡月笼沙，还宿河桥深处。","无情画舸，都不管、烟波隔南浦。","等行人、醉拥重衾，载将离恨归去。","因念旧客京华，长偎傍、疏林小槛欢聚。","冶叶倡条俱相识，仍惯见、珠歌翠舞。","如今向、渔村水驿，夜如岁、焚香独自语。","有何人、念我无，梦魂凝想鸳侣。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-241","tags":["宋词三百首"]},{"id":"poem-8cd8e89a17612724a0debe17","title":"送张五𬤇归宣城","author":"王维","dynasty":"唐","verses":["五湖千万里，况复五湖西。","渔浦南陵郭，人家春谷谿。","欲归江淼淼，未到草萋萋。","忆想兰陵镇，可宜猿更啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-421ddc1d-95a0-40a6-97c2-014d3d97c210","tags":[]},{"id":"poem-8ce2dd36a81b084c6472467f","title":"奉和九日幸临渭亭登高应制得樽字","author":"于经野","dynasty":"唐","verses":["御气三秋节，登高九曲门。","桂筵罗玉俎，菊醴溢芳樽。","遵渚归鸿度，承云舞鹤𬸣。","微臣滥陪赏，空荷圣明恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-f25e2481-52d7-4182-af87-4e7b776d33ab","tags":[]},{"id":"poem-8ce341775abab9d27a1c2ec9","title":"和段校书冬夕寄题庐山","author":"刘得仁","dynasty":"唐","verses":["名高身未到，此恨蓄多时。","是夕吟因话，他年必去随。","尝闻庐岳顶，半入楚江湄。","几处悬崖上，千寻瀑布垂。","炉峰松淅沥，湓浦柳参差。","日色连湖白，钟声拂浪迟。","烟梯缘薜荔，岳寺步欹危。","地本饶灵草，林曾出祖师。","石楼霞耀壁，猨树鹤分枝。","细径萦岩末，高窗见海涯。","嵌空寒更极，寂寞夜尤思。","阴谷冰埋术，仙田雪覆芝。","乱泉禅客濑，异迹逸人知。","藓室新开灶，柽潭末了棋。","如何遂闲放，长得在希夷。","空务渔樵事，方无道路悲。","谢公台尚在，陶令柳潜衰。","尘外难相许，人间贵迹遗。","虽怀丹桂影，不忘白云期。","仁者终携手，今朝预赋诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-29ad430b-4f67-43c7-bbd2-0a7020e2a9aa","tags":["庐山"]},{"id":"poem-8ced2cf2b313fd630311486d","title":"送潍州詹倅五首  其五","author":"綦崇礼","dynasty":"宋","verses":["人生乐知己，见遇况国士。","吾身不激昂，孰为报恩子。","荐达有往来，登门愿谁始。","寄谢魏王孙，丹心亦如此。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-470e485d-dfdc-4dd0-9761-ee72c3eb37b4","tags":[]},{"id":"poem-8cfe32ebaec57fa18b4d69d7","title":"寄人二首 一","author":"崔道融","dynasty":"唐","verses":["花上断续雨，江头来去风。","相思春欲尽，未遣酒尊空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8816e6ae-84ad-4db1-b132-c41ce05797f1","tags":[]},{"id":"poem-8d0657a2307a95fa2b9da250","title":"秋夕","author":"杜牧","dynasty":"唐","verses":["红烛秋光冷画屏，轻罗小扇扑流萤。","天阶夜色凉如水，坐看牵牛织女星。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d12edd29-d467-4b19-b3f5-533fa5c8d56a","tags":["唐诗三百首"]},{"id":"poem-8d11ad768c7534817ab6a301","title":"寄净虚上人初至云门","author":"皇甫曾","dynasty":"唐","verses":["寒踪白云里，法侣自提携。","竹径通城下，松门隔水西。","方同沃洲去，不似武陵迷。","仿佛方知处，高峰是会稽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b5cbb21b-6545-4746-995f-b084fca74d5e","tags":[]},{"id":"poem-8d137428fb7204e23f2c85f4","title":"同前已（以）诗代书","author":"马云奇","dynasty":"唐","verses":["故（古）来同病总相怜，不似今人见眼前。","且随浮俗贪趋世，肯料寒灰亦重燃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2775ca59-6375-4f03-91b1-8c73890ee69b","tags":[]},{"id":"poem-8d18e24aac12603693b50412","title":"西江月·月斧修成腻玉","author":"王质","dynasty":"宋","verses":["月斧修成腻玉，风斤琢碎轻冰。","主人无那寿杯深。","倩取花来唤醒。","舞罢绣裀凤蹙，饮阑画阁香凝。","试将花蕊数层层。","犹比长年不尽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-318","tags":[]},{"id":"poem-8d25be3a255e759f771a426f","title":"五祖栽松六祖担柴赞  其一","author":"释了惠","dynasty":"宋","verses":["恨杀老头陀，山移恨不磨。","吾今担头重，为汝种松多。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-4e67dd49-818a-48aa-b5b3-7fe47f323886","tags":[]},{"id":"poem-8d25e590a7ab0b3e7a99c5ef","title":"题刘氏绿映亭  其一","author":"张栻","dynasty":"宋","verses":["凉叶翻翻不受尘，芒鞋藤杖及清晨。","开帘小放前溪入，澄绿光中独岸巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-642f7be2-a679-4697-b59d-8626bc0a0886","tags":[]},{"id":"poem-8d30944426460fbad75fa935","title":"喜迁莺·月波疑滴","author":"史达祖","dynasty":"宋","verses":["月波疑滴。","望玉壶天近，了无尘隔。","翠眼圈花，冰丝织练，黄道宝光相直。","自怜诗酒瘦，难应接、许多春色。","最无赖，是随香趁烛，曾伴狂客。","踪迹。","谩记忆。","老了杜郎，忍听东风笛。","柳院灯疏，梅厅雪在，谁与细倾春碧。","旧情拘未定，犹自学、当年游历。","怕万一，误玉人、夜寒帘隙。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-181","tags":["宋词三百首"]},{"id":"poem-8d35f3abd0bae1eda50f6025","title":"九五","author":"王梵志","dynasty":"唐","verses":["我见那汉死，肚里热如火。","不是惜那汉，恐畏还到我。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4cf4678a-6b75-44a7-87e5-156ffc27e576","tags":[]},{"id":"poem-8d430dc8be33b2a8e2d8e230","title":"点绛唇·小院重帘","author":"毛滂","dynasty":"宋","verses":["小院重帘，那回来处花相向。","迟迟一饷。","记得春模样。","昨夜月明，应照芙蓉帐。","空凝望。","蜂劳蝶攘。","谁在花枝上。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-854","tags":[]},{"id":"poem-8d44637cfd41d89338192db4","title":"杂咏  其二","author":"米芾","dynasty":"宋","verses":["巨舰横江稳不摇，顺浮溟涨午时潮。","江南晴色山无翳，乞与闲人取次描。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a0571096-7190-425a-8c35-e07266cb15cb","tags":[]},{"id":"poem-8d4548640997d97cae318dd6","title":"郊庙歌辞 武后大享拜洛乐章 咸和","author":"不详","dynasty":"唐","verses":["坎泽祠容备举，坤坛祭典爰申。","灵睠遥行秘躅，嘉贶荐委殊珍。","肃礼恭禋载展，翘襟邈志逾殷。","方期交际悬应。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5c7a41e6-d997-46f3-a6b2-bac41d354e35","tags":[]},{"id":"poem-8d47a15a606a8154970e183c","title":"木兰花令·拟古决绝词","author":"纳兰性德","dynasty":"清","verses":["人生若只如初见，何事秋风悲画扇。","等闲变却故人心，却道故心人易变。","骊山语罢清宵半，泪雨霖铃终不怨。","何如薄幸锦衣郎，比翼连枝当日愿。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-1","tags":[]},{"id":"poem-8d5991f4fc86b69ab3dfdcff","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["楼台银铺，遍青山犹如画图。","乾坤似你衰素，添个缟带飞舞。","你擗踊痛哭直恁苦，那堪雪片添凄楚。","休恁地哭，且逆来顺受么。","抑情就理通今古。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5264","tags":[]},{"id":"poem-8d7e5e271ac7e32e50ad79f9","title":"马诗二十三首 十五","author":"李贺","dynasty":"唐","verses":["不从桓公猎，何能伏虎威。","一朝沟陇出，看取拂云飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-321a9b5e-291a-47ae-bce9-c8d80d8018fa","tags":[]},{"id":"poem-8d81f0d140d28e0d17bf18b7","title":"和李仆射西园","author":"张籍","dynasty":"唐","verses":["遇午归闲处，西庭敞四簷。","高眠著琴枕，散帖检书签。","印在休通客，山晴好卷帘。","竹凉蝇少到，藤暗蝶争潜。","晓鹊频惊喜，疎蝉不许拈。","石苔生紫点，栏药吐红尖。","虚坐诗情远，幽探道侣兼。","所营尚胜地，虽俭复谁嫌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-247aeaa0-d69a-4c18-a69f-fc6cf9280161","tags":[]},{"id":"poem-8d83dc080065ae929dda50af","title":"湖南曲","author":"张籍","dynasty":"唐","verses":["潇湘多别离，风起芙蓉洲。","江上人已远，夕阳满中流。","鸳鸯东南飞，飞上青山头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b89c7d43-a354-4903-bb84-b0e3fb1caba8","tags":[]},{"id":"poem-8d84a143048e8c616a683bf1","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦悲介)听说罢姓名家乡，这情苦意切，闷海愁山将我心上撇，不由人不泪珠流血！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3073","tags":[]},{"id":"poem-8d8c6c908773e0916855f5b8","title":"诉衷情·香灭帘垂春漏永","author":"顾敻","dynasty":"五代","verses":["香灭帘垂春漏永，整鸳衾。","罗带重，双凤，缕黄金。","窗外月光临，沉沉。","断肠无处寻，负春心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-19","tags":[]},{"id":"poem-8d9c347c3a329d6015ae5e65","title":"兵要望江南 医方第二十九（十六首） 十五","author":"易静","dynasty":"唐","verses":["军人众，涉水冒霜多。","手脚面皮皆裂拆，麦叶浓煮汁相过，热洗即安和。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-db486195-0b9d-490f-bf3a-178ad1c3d657","tags":[]},{"id":"poem-8daf92916022eecd44ea0600","title":"秋中霖雨","author":"佚名","dynasty":"唐","verses":["寒雨霖霖竟不停，覊愁寂寂夜何宁？","山遥塞阔阻乡国，草白风悲感客情。","西瞻瀚海肠堪断，东望咸秦思转盈。","才薄孰知无所用，独嗟戎俗滞微名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7e2ef05b-1d4b-487f-b074-56917b2d0637","tags":[]},{"id":"poem-8dce8251ebd0f73ef62ed27f","title":"芙蓉馆","author":"陈岩","dynasty":"宋","verses":["拂壁留诗墨尚鲜，如今屈指五年前。","直须强健常来此，到老宁消几五年。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-2754174c-9ad5-4346-ba73-bb8e128b9461","tags":[]},{"id":"poem-8de05589a1bfa7f7de0e39f2","title":"南歌子·懒拂鸳鸯枕","author":"温庭筠","dynasty":"唐","verses":["懒拂鸳鸯枕，休缝翡翠裙。","罗帐罢炉熏，近来心更切，为思君。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-43","tags":[]},{"id":"poem-8de1ee80007fb649d9a401c7","title":"西湖夜归观打鱼怀赵京兆","author":"释居简","dynasty":"宋","verses":["德人天游乐者全，亦以此乐均鱼鸢。","陶然亦复忘所乐，西湖澄澈如心渊。","管领西湖人不少，前后无如赵京兆。","至今画手画西湖，不著绿蓑人独钓。","胡为今夜月满湖，大船小船皆得鱼。","鱼登罔罟叫不得，那知老子今归欤。","滔滔京兆万人海，平地翻涛渺无盖。","活鱼之外尤活人，人在甘棠颂遗爱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-f5e66d90-8f34-4ade-9987-20ec6e7a1060","tags":["西湖"]},{"id":"poem-8de5f6919c6b3d430b678498","title":"杨柳枝·万株枯槁怨亡隋","author":"孙光宪","dynasty":"五代","verses":["万株枯槁怨亡隋，似吊吴台各自垂。","好是淮阴明月里，酒楼横笛不胜吹。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-44","tags":[]},{"id":"poem-8dee70d8032890d0550693d0","title":"噫嘻","author":"佚名","dynasty":"先秦","verses":["噫嘻成王，既昭假尔。率时农夫，播厥百谷。骏发尔私，终三十里。亦服尔耕，十千维耦。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-276","tags":[]},{"id":"poem-8e201e6b7b623963a74fae94","title":"江南杂题三十首 其二十","author":"张祜","dynasty":"唐","verses":["余生唯爱酒，师长是山翁。","定葬槽丘下，须沉酿瓮中。","鹈鸪春作鸟，舂黍夏为虫。","会入醉乡去，为君成醉风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ccaf5bb1-f4ef-41d7-908e-ece6b228524f","tags":[]},{"id":"poem-8e20a30c56a14419cf036d2c","title":"偈颂七十一首  其二四","author":"释了惠","dynasty":"宋","verses":["诸佛诸祖，邪入肺腑。","无药可医，无术可取。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8c4e8e2d-5832-4b87-8139-25ccb8ea8fbb","tags":[]},{"id":"poem-8e26974030893e1ed0f90aaa","title":"今岁兰柳相先梅最后  其二","author":"释居简","dynasty":"宋","verses":["长是年年趁雪妍，一鞭迟著笑今年。","姓名虽在百花上，终不敢为天下先。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9a21f629-7e8b-403b-bd0d-487e89169cc1","tags":[]},{"id":"poem-8e276776603c7827ae3a13ca","title":"浮云三章 三","author":"皎然","dynasty":"唐","verses":["浮云浮云，集于高舂。","高舂蒙蒙，日夕之容。","匪日之夕，浮云之积。","嗟我怀人，忧心如[惄]。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-71677a05-d3f4-4e2c-82a1-6d2212d84729","tags":[]},{"id":"poem-8e2e3aea032d3331d8edd81f","title":"谢李辀再到","author":"孟郊","dynasty":"唐","verses":["等闲拜日晚，夫妻独相疮。","况是贤人冤，何必哭飞杨。","昨夜梦得劒，为君藏中肠。","会将当风烹，血染布衣裳。","劳君又扣门，词句失寻常。","我不忍出厅，血字湿土墙。","血字耿不灭，我心惧惶惶。","会有铿锵夫，见之目生光。","生光非等闲，君其且安祥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-17678211-6bd8-4c2c-9ed9-cec4de707be0","tags":[]},{"id":"poem-8e316d1c580a204ab35d9e50","title":"苏东坡挽诗五首  其三","author":"米芾","dynasty":"宋","verses":["小冠白㲲步东园，原是青城欲度仙。","六合著名犹似窄，八周御魅讫能旋。","道如韩子频离世，文比欧公复并年。","我不衔恩畏清议，束刍难致泪潸然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1e64a2d2-95d4-4ffa-9d17-e3a283507364","tags":[]},{"id":"poem-8e333eac15b640fc3469ec97","title":"初春和折子明岁前两诗  其一","author":"张栻","dynasty":"宋","verses":["古今同活法，妙处在阿堵。","浮云不作祟，白黑可坐数。","穷冬掩关卧，岂为作诗苦。","挑灯读韦编，至味可深咀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-156d3f57-9141-4312-b22f-6b7d32ba6b0a","tags":[]},{"id":"poem-8e37e7c859d9c38a3adc18f9","title":"桃红菊","author":"无名氏《张协状元》","dynasty":"元","verses":["野方直入庙中，见一佳人困穷。","似胜花娘子无异，血染得衣衫煞红。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2699","tags":[]},{"id":"poem-8e40d5f5ba3f39ead4ccace3","title":"大臣荐对诗","author":"米芾","dynasty":"宋","verses":["笏引上天梯，鞘鸣奋地雷。","谁云天尺五，亲见玉皇来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d2631436-1870-46ee-aaa1-4563bf96529c","tags":[]},{"id":"poem-8e508788cd0331f6f1af489c","title":"寄岐山林逢吉明府","author":"谭用之","dynasty":"宋","verses":["岐山高与陇山连，制锦无私服晏眠。","鹦鹉语中分百里，凤凰声里过三年。","秦无旧俗云烟媚，周有遗风父老贤。","莫役生灵种杨柳，一枝枝折灞桥边。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-59acb909-bc51-4b86-9207-8c728e494d59","tags":[]},{"id":"poem-8e5f1c070a739bb4f583c772","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","verses":["朔风飘胡雁，惨澹带砂砾。","长林何萧萧，秋草萋更碧。","北里富熏天，高楼夜吹笛。","焉知南邻客，九月犹𫄨绤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1bcd81fb-6fb5-4994-b9ec-6baf5bbd4142","tags":[]},{"id":"poem-8e6006d77ba8e738d7766cca","title":"送冯温往河外","author":"薛能","dynasty":"唐","verses":["琴劒事行装，河关出北方。","秦音尽河内，魏画自黎阳。","野日村苗熟，秋霜馆叶黄。","风沙问船处，应得立清漳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-31b9eaa8-608b-47f3-ad36-c79c48f39ecb","tags":[]},{"id":"poem-8e71ca2432fa1c052c6ca342","title":"途中口号","author":"卢僎","dynasty":"唐","verses":["抱玉三朝楚，怀书十上秦。","年年洛阳陌，花鸟弄归人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-05c58936-42d2-4418-87b3-0e60e3c0b046","tags":[]},{"id":"poem-8e74eb53113b3628aae999e2","title":"清平乐·春愁南陌","author":"韦庄","dynasty":"五代","verses":["春愁南陌，故国音书隔。","细雨霏霏梨花白，燕拂画帘金额。","尽日相望王孙，尘满衣上泪痕。","谁向桥边吹笛，驻马西望销魂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-45","tags":[]},{"id":"poem-8e79412748189083f649339a","title":"清明","author":"杜甫","dynasty":"唐","verses":["著处繁花务是日，长沙千人万人出。","渡头翠柳艳明眉，争道朱蹄骄啮膝。","此都好游湘西寺，诸将亦自军中至。","马援征行在眼前，葛强亲近同心事。","金镫下山红粉晚，牙樯捩柁青楼远。","古时丧乱皆可知，人世悲欢暂相遣。","弟姪虽存不得书，干戈未息苦离居。","逢迎少壮非吾道，况乃今朝更祓除。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-de7404b1-b2f2-4924-b187-b47aa50039d7","tags":[]},{"id":"poem-8e7c8678c3167046eb371526","title":"洞仙歌·相如当日","author":"曾纡","dynasty":"宋","verses":["相如当日，曾奏凌云赋。","落笔纵横妙风雨。","记扬鞭辇路，同醉金明，穷胜赏，不管重城已暮。","旧游如梦觉，零落朋侪，遗墨淋漓尚如故。","况神洲北望，今已丘墟，伤白璧、久埋黄土。","但空似、灵光岿然存，怅朗月清风，更无玄度。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-70","tags":[]},{"id":"poem-8e7e3dd16c998f4e5ea3c0c7","title":"行经华阴","author":"崔颢","dynasty":"唐","verses":["岧嶤太华俯咸京，天外三峰削不成。","武帝祠前云欲散，仙人掌上雨初晴。","河山北枕秦关险，驿树西连汉畤平。","借问路傍名利客，无如此处学长生。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-39b2954c-04df-4561-ad6e-f4ddbae0db1e","tags":["唐诗三百首","七言律诗","怀古","山水"]},{"id":"poem-8e81d9af2d369ab67100897b","title":"自河西归山二首 一","author":"司空图","dynasty":"唐","verses":["一水悠悠一叶危，往来长恨阻归期。","乡关不是无华表，自为多惊独上迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-61cd8313-81aa-4d92-813d-06250a628bff","tags":[]},{"id":"poem-8e85c0231dde1ff5443b1572","title":"送韦侍御奉使江岭诸道催青苗钱","author":"包何","dynasty":"唐","verses":["近远从王事，南行处处经。","手持霜简白，心在夏苗青。","回鴈书应报，愁猨夜屡听。","因君使绝域，方物尽来庭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c5f9b99b-fe97-4eef-8fea-30b45125aa97","tags":[]},{"id":"poem-8e8a2ad95359732fd2a4e508","title":"淮阴夜宿二首 二","author":"孙逖","dynasty":"唐","verses":["永夕卧烟塘，萧条天一方。","秋风淮水落，寒夜楚歌长。","宿莽非中土，鲈鱼岂我乡。","孤舟行已倦，南越尚茫茫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-103fde91-0c2f-4bc6-8502-de2bf38b26f2","tags":[]},{"id":"poem-8e965355679ef226ecf10f98","title":"送王储詹事西游献兵书","author":"卢仝","dynasty":"唐","verses":["美酒拨醅酌，杨花飞尽时。","落日长安道，方寸无人知。","箧中制胜术，气雄屈指筭。","半醉千殷勤，仰天一长叹。","玉匣百炼劒，龟文又龙吼。","抽赠王将军，勿使虚白首。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-4b58760b-e78a-4364-abca-7d70d797939d","tags":[]},{"id":"poem-8e9ee39ed39917e5aa8ffd2b","title":"菩萨蛮 其三","author":"温庭筠","dynasty":"唐","verses":["蕊黄无限当山额，宿妆隐笑纱窗隔。","相见牡丹时，暂来还别离。","翠钗金作股，钗上蝶双舞。","心事竟谁知，月明花满枝。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-2","tags":[]},{"id":"poem-8ea4b98ae0f5b7ea0bcc0016","title":"武陵春·春在前村梅雪里","author":"毛滂","dynasty":"宋","verses":["春在前村梅雪里，一夜到千门。","玉佩琼琚下冷云。","银界见东君。","桃花髻暖双飞燕，金字巧宜春。","寂寞溪桥柳弄晴。","老也探花人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-848","tags":[]},{"id":"poem-8eaab9f0768acbe7efdd994c","title":"颂古四首  其三","author":"释行机","dynasty":"宋","verses":["青蛇提起气腥臊，几个男儿有痛毛。","直下血流犹未觉，举头还见铁山高。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-f8939583-4261-4248-bdd4-bc2dcebfa06f","tags":[]},{"id":"poem-8ead3523301a438c4787cfc0","title":"阮郎归·深亭邃馆锁清风","author":"张抡","dynasty":"宋","verses":["深亭邃馆锁清风。","榴花芳艳浓。","阳光染就欲烧空。","谁能窥化工。","观物外，喻身中。","灵砂别有功。","若将一粒比花容。","金丹色又红。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-905","tags":[]},{"id":"poem-8ebb242e2c6a1dc82f5df2a1","title":"偈颂（幷序○序为南岳齐己撰） 八十三","author":"居遁","dynasty":"唐","verses":["唯念深秋扇，临冬转就闲。","银装将物裹，篾作插簷间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0f20c6c0-aa7c-4c6c-ad56-192840db3306","tags":["衡山"]},{"id":"poem-8ebdcd0768f0ad189f673c35","title":"寄题江山叶氏翠香亭  其一","author":"王柏","dynasty":"宋","verses":["此君来与小山盟，共挹周扬一世英。","何用偷它当日意，男儿自要立芳名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-cd79d818-5cbf-4f6e-b3ed-597abbe04353","tags":[]},{"id":"poem-8ec0693aeea9a8d7dcb072d0","title":"次孙元中至后五日游蔡氏园韵","author":"刘跂","dynasty":"宋","verses":["林深宜夏炎，亦复便冬冷。","居然安稳处，合是招提境。","晴烟起屋脊，煦日下天井。","饱饭策杖出，如行赞公岭。","平生一丘壑，快眼春睡醒。","谁言城市喧，能比郊原静。","人间会合少，万事等泡影。","适意不自取，兀立真土梗。","时平日月好，岁熟羁旅幸。","逢人但懽喜，得酒便酩酊。","知我非子谁，频来不须请。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-bfb0d708-4f50-4294-8f5a-f8d9c62ad283","tags":[]},{"id":"poem-8ec088b0d904e4a79299351c","title":"古塞上曲七首 一","author":"贯休","dynasty":"唐","verses":["幽幷儿百万，百战未曾输。","蕃界已深入，将军仍远图。","月明风拔帐，碛暗鬼骑狐。","但有东归日，甘从筋力枯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-db2e6b95-1383-4d00-8fa6-ff3ac7779bf7","tags":[]},{"id":"poem-8edb441232ad053eb8922e0b","title":"敬之","author":"佚名","dynasty":"先秦","verses":["敬之敬之，天维显思，命不易哉。无曰高高在上，陟降厥士，日监在兹。","维予小子，不聪敬止。日就月将，学有缉熙于光明。佛时仔肩，示我显德行。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-287","tags":[]},{"id":"poem-8ee056fd0ce84d0c1560c418","title":"金鸡叫","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(贴上)不听好言语，镇日间无情无绪。","羡我院君多伶俐，设下机谋，手足又和美。","我员外当初听信乔人，赶出兄弟。","我院君杀狗劝夫，回心转意，弟兄和睦。","不想柳龙卿、胡子传今早又到我家，道员外不睬，又到官府出首员外杀人，小官人埋尸。","为此院君亲往府尹处诉明，尚未回来，不知怎生决断了？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1959","tags":[]},{"id":"poem-8ee1f7344050391391295e3f","title":"醉太平","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["蹉跎，光阴易谢。","纵归来已晚，归计无暇。","名牵利锁，奔走在海角天涯。","知么？多应我老死在京华，孝情事一笔都勾罢。","这般摧锉，伤情万感，泪珠偷随。","(贴唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5182","tags":[]},{"id":"poem-8eebd9ff60c1f6811b077bb6","title":"八节长欢·名满人间","author":"毛滂","dynasty":"宋","verses":["名满人间。","记黄金殿，旧赐清闲。","才高鹦鹉赋，风懔惠文冠。","涛波何处试蛟鳄，到白头、犹守溪山。","且做龚黄样度，留与人看。","桃溪柳曲阴圆。","离唱断、旌旗却卷春还。","襦裤寄馀温，双石畔、唯闻吏胆长寒。","诗翁去，谁细绕、屈曲阑干。","从今后、南来幽梦，应随月度云端。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-776","tags":[]},{"id":"poem-8eee6c3e09033db5345eabf4","title":"元日早朝","author":"王建","dynasty":"唐","verses":["大国礼乐备，万邦朝元正。","东方色未动，冠劒门已盈。","帝居在蓬莱，肃肃钟漏清。","将军领羽林，持戟巡宫城。","翠华皆宿陈，雪仗罗天兵。","庭燎远煌煌，旗上日月明。","圣人龙火衣，寝殿开旋扃。","龙楼横紫烟，宫女天中行。","六蕃倍位次，衣服各异形。","举头看玉牌，不识宫殿名。","左右雉扇开，蹈舞分满庭。","朝服带金玉，珊珊相触声。","泰阶备雅乐，九奏鸾凤鸣。","裴回庆云中，竽磬寒铮铮。","三公再献寿，上帝锡永贞。","天明告四方，群后保太平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a9efd292-5e45-487a-b4ad-fec81366b5c3","tags":[]},{"id":"poem-8eef8c37aa89bcce5da6d0b3","title":"重忆山居六首 漏潭石","author":"李德裕","dynasty":"唐","verses":["常疑六合外，未信漆园书。","及此闻溪漏，方欣验尾闾。","大哉天地气，呼吸有盈虚。","美石劳相赠，琼瑰自不如。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-805feea3-9669-4ea8-a097-d50534875e13","tags":[]},{"id":"poem-8ef499f96000b1790f4f9307","title":"牧童","author":"释居简","dynasty":"宋","verses":["蓬松袒跣倒骑牛，折得山花便满头。","强使倡歌浑不听，听它天籁自鸣休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-1ff30515-a36a-4445-8d41-1aa25492e063","tags":[]},{"id":"poem-8eff0726e9f7a3b3e271e5c6","title":"自咏三首 二","author":"卢仝","dynasty":"唐","verses":["卢子𨀁踵也，贤愚总莫惊。","蚊蝱当家口，草石是亲情。","万卷堆胸朽，三光撮眼明。","翻悲广成子，闲气说长生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-490f56b2-c972-4c28-a4d2-0af9e7aa7b68","tags":[]},{"id":"poem-8f05538b0bb9c24672d55e69","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十二","author":"易静","dynasty":"唐","verses":["乙奇墓，未上望坤方。","丙奇（辛本、川本作「其」）戍地酉中是，丁奇同位戌干（辛本、川本作「朝」）张，都是审明方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-cfff4e1a-ae37-49c5-a18b-01f56856b6c8","tags":[]},{"id":"poem-8f0fde1e04e16fdb3bc85917","title":"驻马听","author":"施惠《幽闺记》","dynasty":"元","verses":["(生、旦上)一路里奔驰，多少艰辛，来到这里。","且喜略时才肃静，渐次平安，稍而宁息。","恨悠悠千里旅情悲，苦恹恹一片乡心碎。","感叹咨嗟，伤情满眼关山泪。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2976","tags":[]},{"id":"poem-8f111841e26c91e2d6923243","title":"野有死麕","author":"佚名","dynasty":"先秦","verses":["野有死麕，白茅包之。有女怀春，吉士诱之。","林有朴樕，野有死鹿。白茅纯束，有女如玉。","舒而脱脱兮，无感我帨兮，无使尨也吠。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-22","tags":[]},{"id":"poem-8f1120647442651199da7dbf","title":"醉翁子","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["非悭。","论治家千难万难，休只管吃得瓮尽杯干。","［丑］今番，庆生席面，难做寻常一例看。","［合］重换盏，直饮到月转花梢，影上阑杆。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8033","tags":[]},{"id":"poem-8f1804dbd614c80b4399e648","title":"与邓州行者颂","author":"智闲","dynasty":"唐","verses":["林下觉身愚，缘不带心珠。","开口无言说，笔头无可书。","人问香严旨，莫道在山居。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d9d69bb5-ff88-4166-9540-8eabf978ba0b","tags":[]},{"id":"poem-8f18d8aeee4b14aa0bda2ac6","title":"应天长·玉楼春望晴烟灭","author":"牛峤","dynasty":"五代","verses":["玉楼春望晴烟灭，舞衫斜卷金条脱。","黄鹂娇啭声初歇，杏花飘尽龙山雪。","凤钗低赴节，筵上王孙愁绝。","鸳鸯对含罗结，两情深夜月。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-8","tags":[]},{"id":"poem-8f197fea5f94cae7e0838bf7","title":"横吹曲辞 出塞曲 二","author":"僧贯休","dynasty":"唐","verses":["玉帐将军意，慇懃把酒论。","功高宁在我，阵没与招魂。","塞色干戈束，军容喜气屯。","男儿今始是，敢出玉关门。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-de9b3a1a-925d-445a-9e23-d03b0f64d388","tags":[]},{"id":"poem-8f2302f8fe1a381ab8fd37d0","title":"上长庆和尚偈（题拟）","author":"王延彬","dynasty":"唐","verses":["世人悟道非从耳，耳患虽加道亦分。","灵鹫一机迦叶会，吾师传得岂关闻。","（《祖堂集》卷十。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0b40f654-43bd-4384-97f2-e24dfed1daec","tags":[]},{"id":"poem-8f2aaf520cdc5f9b53664c58","title":"东郡怀古二首 王京兆","author":"李德裕","dynasty":"唐","verses":["河水昔将决，冲波溢川浔。","峥嵘金堤下，喷薄风雷音。","投马灾未弭，为鱼叹方深。","惟公执珪璧，誓与身俱沈。","诚信不虚发，神明宜尔临。","湍流自此回，咫尺焉能侵。","逮我守东郡，凄然怀所钦。","虽非识君面，自谓知君心。","意气苟相合，神明无古今。","登城见遗庙，日夕空悲吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-00eca35e-b0b6-432a-a14e-2d28ca08e3ca","tags":[]},{"id":"poem-8f2ed26906bcc51dced05fc4","title":"终南别业","author":"王维","dynasty":"唐","verses":["中岁颇好道，晚家南山陲。","兴来每独往，胜事空自知。","行到水穷处，坐看云起时。","偶然值林叟，谈笑无还期。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6d098c75-038d-45f4-8f86-73976c355e44","tags":["唐诗三百首","田园","抒情","五言律诗","山","写人"]},{"id":"poem-8f4f72a68cb4e0b4395c3085","title":"登垅","author":"高适","dynasty":"唐","verses":["垅头远行客，垅上分流水。","流水无尽期，行人未云已。","浅才登一命，孤劒通万里。","岂不思故乡，从来感知己。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-dcccde71-c438-4fa8-ac7a-a9ac53638a7c","tags":[]},{"id":"poem-8f4fff5df7cef30b730a5908","title":"次孙君汝弼晚步韵","author":"刘跂","dynasty":"宋","verses":["寂寥谁过仲宣楼，邂逅斯人肯小留。","多病儿童便食粥，忘机鸥鸟共临流。","赋成拟学张平子，志大空惭马少游。","载酒从今相煖热，著书应不号穷愁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-39ab82c2-0aba-4fa1-a67c-2ba6c7d38e95","tags":[]},{"id":"poem-8f5e5a5d9dffecfcc46dd8b5","title":"赠孔尚书","author":"张籍","dynasty":"唐","verses":["能将直道历荣班，事著元和实录间。","三表自陈辞北阙，一家相送入南山。","买来侍女教人嫁，赐得朝衣在箧闲。","宅近青山高静处，时归林下暂开关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-68da5949-d64b-4058-85e9-ccdf23dd687c","tags":[]},{"id":"poem-8f5f927506fe92936a4a68da","title":"萚兮","author":"佚名","dynasty":"先秦","verses":["萚兮萚兮，风其吹女。叔兮伯兮，倡予和女。","萚兮萚兮，风其漂女。叔兮伯兮，倡予要女。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-84","tags":[]},{"id":"poem-8f63df291e3be64a39ef463c","title":"采桑子·九日","author":"纳兰性德","dynasty":"清","verses":["深秋绝塞谁相忆，木叶萧萧。","乡路迢迢。","六曲屏山和梦遥。","佳时倍惜风光别，不为登高。","只觉魂销。","南雁归时更寂寥。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-87","tags":[]},{"id":"poem-8f762a30d687df61d5f58653","title":"宿普济寺","author":"刘得仁","dynasty":"唐","verses":["京寺数何穷，清幽此不同。","曲江临阁北，御苑自墙东。","广陌车音急，危楼夕景通。","乱峰沈暝野，毒暑过秋空。","幡扬虚无里，星生杳霭中。","月光笼月殿，莲气入莲宫。","缀草凉天露，吹人古木风。","饮茶除假寐，闻磬释尘蒙。","童子眠苔净，高僧话漏终。","待鸣晓钟后，万井复朣胧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-972f30a9-b76a-47e1-b075-2816554d79c5","tags":[]},{"id":"poem-8f794cf632101d8399cf1c58","title":"宛陵送李明府罢任归江州","author":"来鹄","dynasty":"唐","verses":["菊花村晚雁来天，共把离觞向水边。","官满便寻垂钓侣，家贫已用卖琴钱。","浪生湓浦千层雪，云起炉峰一炷烟。","倘见吾乡旧知己，为言顦顇过年年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ac77a741-d6cc-4047-9e9e-e708f0f2d22e","tags":[]},{"id":"poem-8f7955f19f39d4e42e8bb825","title":"十无诗寄桂府杨中丞 十","author":"赵嘏","dynasty":"唐","verses":["膺门不避额逢珠，绝境由来卷轴须。","早忝阿戎诗友契，趋庭曾荐祢生无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-21c2e074-4b54-4742-83af-3a05c76be088","tags":[]},{"id":"poem-8f79649c772f0ff3529eb841","title":"鼓吹曲辞 巫山高","author":"皇甫冉","dynasty":"唐","verses":["巫峡见巴东，迢迢半出空。","云藏神女馆，雨到楚王宫。","朝暮泉声落，寒暄树色同。","清猨不可听，偏在九秋中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e607091f-25b1-4d3b-96f0-f5e8fa16bea1","tags":[]},{"id":"poem-8f7cfc737859c85d740bb19a","title":"和三乡诗","author":"韦冰","dynasty":"唐","verses":["来时欢笑去时哀，家国迢迢向越台。","待写百年幽思尽，故宫流水莫相催。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-83a8c92c-5c97-469b-a2aa-e1c411934cf0","tags":[]},{"id":"poem-8f7d712e0c84b4cab5fd64c3","title":"暇日题草堂","author":"钱起","dynasty":"唐","verses":["为郎过壮岁，晚景对秋天。","门掩苍苔上，池清寒竹前。","通经未拾紫，炼药不成仙。","且酝东臯黍，愁来得醉眠。","（见宋赵师秀编选《唐众妙集》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5627f48a-ef9a-4e6e-9148-1aecc0be921d","tags":[]},{"id":"poem-8f818994770a72d5380818c4","title":"玉台体十二首 十一","author":"权德舆","dynasty":"唐","verses":["昨夜裙带解，今朝蟢子飞。","铅华不可弃，莫是藁砧归。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9a5070c8-8b6a-46d3-a976-ce942baf42e7","tags":["唐诗三百首","思念","五言绝句","女子"]},{"id":"poem-8f8394d9206bf1ec287bed05","title":"采莲子·船动湖光滟滟秋","author":"皇甫松","dynasty":"唐","verses":["船动湖光滟滟秋（举棹），贪看年少信船流（年少）。","无端隔水抛莲子（举棹），遥被人知半日羞（年少）。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-27","tags":[]},{"id":"poem-8f84b1e9fd3de78607edf710","title":"古歌","author":"沈佺期","dynasty":"唐","verses":["落叶流风向玉台，夜寒秋思洞房开。","水晶帘外金波下，云母窗前银汉回。","玉阶阴阴苔藓色，君王屡綦难再得。","璇闺窈窕秋夜长，绣户徘徊明月光。","燕姬彩帐芙蓉色，秦女金炉兰麝香。","北斗七星横夜半，清歌一曲断君肠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-01b06a31-10d7-448a-9207-04096ca4610a","tags":[]},{"id":"poem-8f8606765fef54c7b650449b","title":"河南府试十二月乐词 五月","author":"李贺","dynasty":"唐","verses":["雕玉押帘额，轻縠笼虚门。","井汲铅华水，扇织鸳鸯纹。","回雪舞凉殿，甘露洗空绿。","罗袖从徊翔，香汗沾宝粟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c0b70e60-687b-4300-a82f-5ef31807f377","tags":[]},{"id":"poem-8f869324f498d4362643eaaf","title":"江上送客","author":"李端","dynasty":"唐","verses":["故人南去汉江阴，秋雨萧萧云梦深。","江上见人应下泪，由来远客易伤心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-64df610f-2fd8-479f-8ed5-8f87799e634d","tags":[]},{"id":"poem-8f9d3f0e9b0e93341abda5f2","title":"杨柳枝·御柳如丝映九重","author":"温庭筠","dynasty":"唐","verses":["御柳如丝映九重，凤凰窗映绣芙蓉。","景阳楼畔千条路，一面新妆等晓风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-35","tags":[]},{"id":"poem-8f9e6d56efae2aade273ffe9","title":"答资道","author":"刘跂","dynasty":"宋","verses":["都尉声名后，篇章不乏才。","谈高正始际，诗自建安来。","险怪探龙颔，甘珍味豹胎。","阴何长有思，郊岛漫相猜。","白雪凭谁听，黄花入众咍。","楚醒搴水薜，蜀兴动官梅。","晚艇翩翩鸟，秋涛隠隠雷。","水兼天浩荡，山为日崔嵬。","丽藻烦三复，愁肠殆九回。","自惭无世用，庄语笑迂骀。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-27e7800c-5161-4613-8e2e-021cbd3c3d4f","tags":[]},{"id":"poem-8fa0864c31fd374e61f16f83","title":"忆过润州","author":"李绅","dynasty":"唐","verses":["昔年从宦干戈地，黄绶青春一鲁儒。","弓犯控弦招武旅，劒当抽匣问狂夫。","帛书投笔封鱼腹，玄发冲冠捋虎须。","谈笑谢金何所媿，不为偷买用兵符。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b2b78bd9-0bf1-447b-afea-4b7f5ad48e71","tags":[]},{"id":"poem-8fa90d1d84c4a36cc5ab1964","title":"婺州宴上留别","author":"赵嘏","dynasty":"唐","verses":["双溪楼影向云横，歌舞高台晚更清。","独自下楼骑瘦马，摇鞭重入乱蝉声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-83a5843a-5c93-42cc-ac96-02a6e96e00e1","tags":[]},{"id":"poem-8faa871e540d0e5825a8d345","title":"咏宣律和尚袈裟","author":"张希复","dynasty":"唐","verses":["共覆三衣中夜寒，披时不镇尼师坛。","无因盖得龙宫地，畦里尘飞叶相残。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-05e59e1f-fd53-47a0-a83c-1fce7862686a","tags":[]},{"id":"poem-8fb280e06f4839a5fa7ea056","title":"金蕉叶","author":"杨景贤","dynasty":"元","verses":["正待要扫筝擘阮，忽受取观音差遣。","西天路妖魔万千，保护着唐僧庶免。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4527","tags":[]},{"id":"poem-8fb721ef3d58d74437d16c3c","title":"破阵子·燕子来时新社","author":"晏殊","dynasty":"宋","verses":["燕子来时新社，梨花落后清明。","池上碧苔三四点，叶底黄鹂一两声。","日长飞絮轻。","巧笑东邻女伴，采桑径里逢迎。","疑怪昨宵春梦好，元是今朝斗草赢。","笑从双脸生。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-561","tags":[]},{"id":"poem-8fbab12060e2a09740017b5d","title":"送姚合郎中任杭州","author":"刘得仁","dynasty":"唐","verses":["水陆中分程，看花一月行。","会稽山隔浪，天竺树连城。","候吏赍鱼印，迎船载斾旌。","渡江春始半，列屿草初生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-303ad4fe-b67f-476e-aa48-0de91ba3e9f4","tags":[]},{"id":"poem-8fbd9d9daff860272ec4e7f4","title":"寄远","author":"马戴","dynasty":"唐","verses":["坐想亲爱远，行嗟天地阔。","积疹甘毁颜，沈忧更销骨。","迢迢游子心，望望归云没。","乔木非故里，高楼共明月。","夜深秋风多，闻鴈来天末。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-a8e9af2a-ed90-4b8a-8fcf-b5fc625e3c37","tags":[]},{"id":"poem-8fbf3e98351ef68937cfb4fd","title":"出猎","author":"太宗皇帝","dynasty":"唐","verses":["楚王云梦泽，汉帝长杨宫。","岂若因农暇，阅武出轘嵩。","三驱陈锐卒，七萃列材雄。","寒野霜氛白，平原烧火红。","雕戈夏服箭，羽骑绿沈弓。","怖兽潜幽壑，惊禽散翠空。","长烟晦落景，灌木振严风。","所为除民瘼，非是悦林丛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-822d55ea-2b24-4067-a997-106adf6d6f55","tags":[]},{"id":"poem-8fc3e3617a305bf6fa6ad586","title":"卢令","author":"佚名","dynasty":"先秦","verses":["卢令令，其人美且仁。","卢重环，其人美且鬈。","卢重鋂，其人美且偲。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-102","tags":[]},{"id":"poem-8fc9ae9f5b24ab3d750ed6c6","title":"酬王哦松八景  其七","author":"释居简","dynasty":"宋","verses":["雨后双螺对绾青，采毫曾此蘸中泠。","冩成九派分流势，不冩当年瘗鹤铭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3fabf970-4bbb-43d0-9e61-901124454f5e","tags":[]},{"id":"poem-8fd1499fd17fb56128969f5d","title":"古苑杏花","author":"张籍","dynasty":"唐","verses":["废苑杏花在，行人愁到时。","独开新堑底，半露旧烧枝。","晚色连荒辙，低阴覆折碑。","茫茫古陵下，春尽又谁知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0872f854-66eb-44bb-b652-da68abad8429","tags":[]},{"id":"poem-8fd43ec074b259f1ec2457b5","title":"句  其一","author":"谢景初","dynasty":"宋","verses":["倒著衣裳迎户外，尽呼儿女拜灯前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-3ec70516-c959-4668-9a4b-6b1d7364279b","tags":[]},{"id":"poem-8fd87d3473ab1b9bfd27fcfc","title":"游长宁公主流杯池二十五首 十九","author":"上官昭容","dynasty":"唐","verses":["暂游仁智所，萧然松桂情。","寄言栖遯客，勿复访蓬瀛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-dd4c3198-29e8-4d2a-bdb1-184ba15f7d3d","tags":[]},{"id":"poem-8fdceb3319e6976309d1d4dd","title":"十月诞辰内殿宴群臣效柏梁体联句","author":"中宗皇帝","dynasty":"唐","verses":["润色鸿业寄贤才，叨居右弼媿盐梅。","运筹帷幄荷时来，职掌图籍滥蓬莱。","两司谬忝谢钟裴，礼乐铨管效涓埃。","陈师振旅清九垓，欣承顾问侍天杯。","衔恩献寿梁柏台，黄缣青简奉康哉。","鲰生侍从忝王枚，右掖司言实不才。","宗伯秩礼天地开，帝歌难续仰昭回。","微臣捧日变寒灰，远慙班左媿游陪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-49359d18-613c-4aa0-8836-e2253b88d772","tags":[]},{"id":"poem-8fdec65ad33308cdb7831d08","title":"菩萨蛮·为春憔悴留春住","author":"纳兰性德","dynasty":"清","verses":["为春憔悴留春住，那禁半霎催归雨。","深巷卖樱桃，雨余红更娇。","黄昏清泪阁，忍便花飘泊。","消得一声莺，东风三月情。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-148","tags":[]},{"id":"poem-8fe546c0a252e841c892127d","title":"次雷州","author":"李纲","dynasty":"宋","verses":["华夷图上看雷州，万里孤城据海陬。","萍迹飘流遽如许，骚辞拟赋畔牢愁。","沧溟浩荡烟云晓，鼓角凄悲风露秋。","莫笑炎荒地遐僻，万安更在海南头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d968dfb7-7b2f-4be5-be57-2fecd05d0c74","tags":[]},{"id":"poem-8ff797429d9d4651ed2d6f02","title":"兵要望江南 《周易》占候第二十六（三十七首） 二十一","author":"易静","dynasty":"唐","verses":["爻上见，无鬼又无孙。","但有应方幷世上，以应为他我世军，此克定军情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-22e56ca0-3713-4cae-854f-485dd69f9e2d","tags":[]},{"id":"poem-8fff08fa0ffeffd06179c7cd","title":"东山","author":"佚名","dynasty":"先秦","verses":["我徂东山，慆慆不归。我来自东，零雨其蒙。我东曰归，我心西悲。","制彼裳衣，勿士行枚。蜎蜎者蠋，烝在桑野。敦彼独宿，亦在车下。","我徂东山，慆慆不归。我来自东，零雨其蒙。果臝之实，亦施于宇。","伊威在室，蟏蛸在户。町畽鹿场，熠耀宵行。不可畏也，伊可怀也。","我徂东山，慆慆不归。我来自东，零雨其蒙。鹳鸣于垤，妇叹于室。","洒扫穹窒，我征聿至。有敦瓜苦，烝在栗薪。自我不见，于今三年。","我徂东山，慆慆不归。我来自东，零雨其蒙。仓庚于飞，熠耀其羽。","之子于归，皇驳其马。亲结其缡，九十其仪。其新孔嘉，其旧如之何？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-155","tags":[]},{"id":"poem-9002573e032492c1827312f4","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(净、丑)孙华杀人是实，孙荣移尸去，假妆成狗是乔的。","(生)你不说赏雪醉迷，跌倒在雪儿取，拐玉环你回家去？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1955","tags":[]},{"id":"poem-90052181d1d64221889f80f4","title":"殷武","author":"佚名","dynasty":"先秦","verses":["挞彼殷武，奋伐荆楚。深入其阻，裒荆之旅。有截其所，汤孙之绪。","维女荆楚，居国南乡。昔有成汤，自彼氐羌，莫敢不来享，莫敢不来王。曰商是常。","天命多辟，设都于禹之绩。岁事来辟，勿予祸适，稼穑匪解。","天命降监，下民有严。不僭不滥，不敢怠遑。命于下国，封建厥福。","商邑翼翼，四方之极。赫赫厥声，濯濯厥灵。寿考且宁，以保我后生。","陟彼景山，松伯丸丸。是断是迁，方斫是虔。松桷有梴，旅楹有闲，寝成孔安。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-304","tags":[]},{"id":"poem-90081962902a1fd2e1d7391a","title":"渔家傲·灰暖香融销永昼","author":"周邦彦","dynasty":"宋","verses":["灰暖香融销永昼。","蒲萄架上春藤秀。","曲角栏干群雀斗。","清明后。","风梳万缕亭前柳。","日照钗梁光欲溜。","循阶竹粉沾衣袖。","拂拂面红如著酒。","沈吟久。","昨宵正是来时候。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-377","tags":[]},{"id":"poem-900fb90c40b4c92dee6a568e","title":"喜迁莺·长江千里","author":"李纲","dynasty":"宋","verses":["长江千里。","限南北、雪浪云涛无际。","天险难逾，人谋克壮，索虏岂能吞噬。","阿坚百万南牧，倏忽长驱吾地。","破强敌，在谢公处画，从容颐指。","奇伟。","淝水上，八千戈甲，结阵当蛇豕。","鞭弭周旋，旌旗麾动，坐却北军风靡。","夜闻数声鸣鹤，尽道王师将至。","延晋祚，庇烝民，周雅何曾专美。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-544","tags":["长江"]},{"id":"poem-90136f65a17ed9bdee6390ce","title":"汉南遇友人","author":"项斯","dynasty":"唐","verses":["此身西复东，何计此相逢。","梦尽吴越水，恨深襄汉钟。","积云开去路，曙雪叠前峰。","谁即知非旧，怜君忽见容。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2efaf05d-7f64-478a-9f78-788ce38571be","tags":[]},{"id":"poem-9039ea784d9c1b8fa8bc3d2e","title":"赠野僧","author":"吕从庆","dynasty":"唐","verses":["有客逃禅住北冈，昔年支许意相当。","清如细竹迎风洒，洁似孤松冒雪张。","锡杖倚雪看远岫，铜瓶汲月煑新汤。","只今石畔双扉掩，静阅琅函日几章。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3a95c924-a94b-46e9-aed9-8869b68b238b","tags":[]},{"id":"poem-903b23d36b296e04790a5a3f","title":"月夜忆舍弟","author":"杜甫","dynasty":"唐","verses":["戍鼓断人行，秋边一雁声。","露从今夜白，月是故乡明。","有弟皆分散，无家问死生。","寄书长不避，况乃未休兵。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c1280e87-ac81-4f9b-9de5-377d6af38ae8","tags":["唐诗三百首","月夜","秋天","边塞","思乡","五言律诗","怀人","中秋"]},{"id":"poem-903ec19d12b37dded87ddfaa","title":"田家作","author":"贯休","dynasty":"唐","verses":["田家老翁无可作，昼甑蒸梨香漠漠。","只向堦前曝背眠，赤桑大叶时时落。","古壍侵门桃竹密，仓囤峨峨欲遮日。","自云孙子解耕耘，四五年来腹多实。","我闻此语心自悲，世上悠悠岂得知，稼而不穑徒尔为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1cfb66ee-9b73-4c33-9fcf-8372639753cf","tags":[]},{"id":"poem-904189f879f54f54e9a14003","title":"爱松堂前有绿竹一丛可爱旁有鹰爪花颇碍眼移去之","author":"王十朋","dynasty":"宋","verses":["窗前栽植不宜繁，松竹相依妙意存。","不许闲花放鹰爪，要看高节迸龙孙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-92b440e3-3536-4cbb-8b33-e22586e240c0","tags":[]},{"id":"poem-905e13a0cf83ab805f0b763c","title":"清平调 三","author":"李白","dynasty":"唐","verses":["名花倾国两相欢，常得君王带笑看。","解得春风无限恨，沈香亭北倚阑干。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f91f3117-2bf2-4d12-999a-aca174124715","tags":["唐诗三百首","乐府","写人","花","写花"]},{"id":"poem-905f8d4d92fdca2f5fbdfe4a","title":"送韩绅卿","author":"李端","dynasty":"唐","verses":["春雨昨开花，秋霜忽沾草。","荣枯催日夕，去住皆须老。","君望汉家原，高坟渐成道。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d3df845a-eee5-4b84-beb4-0bdeb09cf264","tags":[]},{"id":"poem-906193b03e4a7959c477283c","title":"次韵蒋颖叔同游超化院","author":"苏颂","dynasty":"宋","verses":["贤良才识明，御史风望清。","命驾千里至，高谈一座惊。","旧故偶获道，离忧自兹平。","朅来湖上寺，共语堂西楹。","念昔一交臂，几年两摇旌。","契阔信靡定，邂逅欣偕行。","日薄聊顿辔，兴来再飞觥。","霜林陨丹叶，泉坻结新冰。","湖月金炯炯，竹风玉玲玲。","峰峦对三山，楼殿如九成。","南州足奇丽，此地尤兼并。","因君发题咏，足使增嘉声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-bf2c48eb-a924-45a7-a6d0-a9de72e96903","tags":[]},{"id":"poem-906ce23849f070f01c9eec20","title":"送郑宥入蜀迎觐","author":"李端","dynasty":"唐","verses":["宁亲西陟险，君去异王阳。","在世谁非客，还家即是乡。","剑门千转尽，巴水一支长。","请语愁猿道，无烦促泪行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ec92b206-bff8-43a6-ae6b-977430e21bd8","tags":[]},{"id":"poem-906e108c6919187b5ade1539","title":"对月作","author":"贯休","dynasty":"唐","verses":["今人看此月，古人看此月。","如何古人心，难向今人说。","古人求禄以及亲，及之如之何。","忠孝为朱轮，今人求禄唯庇身。","庇身如之何，恶木多斜文。","斜文复斜文，颠窒何纷纷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a2cc6dcf-6c94-4fc7-a3e9-a514310a63b9","tags":[]},{"id":"poem-9086bdb5675dba59de9053ad","title":"玉楼春·九重盛旦薰风候","author":"曹勋","dynasty":"宋","verses":["九重盛旦薰风候。","佳气氛氲横永昼。","眉心烟彩拥群仙，华宴重开同圣后。","箫韶宫殿锵金奏。","香绕祥云腾宝兽。","三千嫔御奉严宸，亿万斯年祈圣寿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-171","tags":[]},{"id":"poem-9089becaa2d23c5666dfd435","title":"贫交行","author":"杜甫","dynasty":"唐","verses":["飜手作云覆手雨，纷纷轻薄何须数。","不见管鲍贫时交，此道今人弃如土。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7014a7a3-6b60-46bc-9631-63c6a724574d","tags":["友情","怀古","愤懑"]},{"id":"poem-9090de32c2865cd9eb5d30cf","title":"卜算子·驿外断桥边","author":"陆游","dynasty":"宋","verses":["驿外断桥边，寂寞开无主。","已是黄昏独自愁，更著风和雨。","无意苦争春，一任群芳妒。","零落成泥碾作尘，只有香如故。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-13","tags":["宋词三百首"]},{"id":"poem-90914caf357540453cac4833","title":"偶诗五首 五","author":"司空图","dynasty":"唐","verses":["中宵茶鼎沸时惊，正是寒窗竹雪明。","甘得寂寥能到老，一生心地亦应平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-06774686-2e23-4309-b84e-83d0de71a64c","tags":[]},{"id":"poem-909473cf3a921cec4eec92ad","title":"奉酬张洪州九龄江上见赠","author":"孙翃","dynasty":"唐","verses":["受命谳封疆，逢君牧豫章。","于焉审虞芮，复尔共舟航。","怅别秋阴尽，怀归客思长。","江臯枉离赠，持此慰他乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-1f5beb19-67e2-4773-b8f8-5effef828301","tags":[]},{"id":"poem-909c2caed7354ee307bb9dc9","title":"最胜亭","author":"陈岩","dynasty":"宋","verses":["烟收雾敛翠成围，来助幽亭眼界奇。","衲子苦于山索句，棱棱瘦骨不禁诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-381e37ea-9b81-4ae8-b864-def0ff637ce3","tags":[]},{"id":"poem-909caed80669079a2fbf900e","title":"颂古三十一首  其七","author":"释玿","dynasty":"宋","verses":["是贼识贼精识精，南泉无过强惺惺。","赵州礼拜归堂去，前箭犹轻后箭深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-903f87d6-f2a6-435e-87dc-1a1db66b24bd","tags":[]},{"id":"poem-909d78df991c261bc2055401","title":"迁居","author":"梅远","dynasty":"唐","verses":["百里犹乡土，千年亦比邻。","愿言培世德，未敢咏维新。","（均见清施念曾、张汝霖编《宛雅三编》卷二、嘉庆廿八年刊洪亮吉等纂《宁国府志》卷二十四。","）（按：梅远为北宋著名诗人梅尧臣的曾祖。","《欧阳文忠公文集》卷三三《梅圣俞墓志铭》云：「曾祖讳远，祖讳邈，皆不仕。","」杨杰《无为集》卷十三《故朝奉郎守殿中丞梅君〖正臣〗墓志铭》云：「南唐末，曾祖远为宣城掾。","」正臣为尧臣弟。","《宛雅三编》卷二引《梅氏诗谱》，谓远字维明，光化间由吴兴之宣城为掾。","以宣之风土淳厚，遂筑居于州学之西，著有《迁居草》。","今按：三书所记稍有出入。","考《欧阳文忠公文集》卷三十一《太子中舍梅君墓志铭》，尧臣父梅让卒于皇祐元年，年九十一，推其生年，为显德六年。","以此推测，梅远约生于十世纪初，以仕南唐为是。","《梅氏诗谱》有误，今不取光化年仕宣说。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-997478ad-a649-4156-b5ab-7ddbbadbd838","tags":[]}];
